css:
.mgr-invoices {
  --mgr-invoices-paper: oklch(0.985 0.009 85);
  --mgr-invoices-ink: oklch(0.25 0.02 55);
  --mgr-invoices-accent: oklch(0.6 0.19 33);
  --mgr-invoices-ok: oklch(0.55 0.1 158);
  --mgr-invoices-line: color-mix(in oklch, var(--mgr-invoices-ink) 11%, transparent);
  --mgr-invoices-dim: color-mix(in oklch, var(--mgr-invoices-ink) 56%, var(--mgr-invoices-paper));
  --mgr-invoices-wash: color-mix(in oklch, var(--mgr-invoices-ink) 4.5%, var(--mgr-invoices-paper));
  --mgr-invoices-spring: linear(0, 0.0174 2%, 0.0635 4%, 0.168 7%, 0.296 10%, 0.474 14%, 0.638 18%, 0.805 23%, 0.922 28%, 1 34%, 1.04 40%, 1.05 46%, 1.04 53%, 1.02 60%, 1.01 70%, 0.999 80%, 1);
  --mgr-invoices-ease: cubic-bezier(.2, .8, .2, 1);
  container-type: inline-size;
  box-sizing: border-box; width: 100%; max-width: 460px; margin-inline: auto;
  padding: 16px 14px 10px; border-radius: 16px;
  background: var(--mgr-invoices-paper); color: var(--mgr-invoices-ink);
  border: 1px solid color-mix(in oklch, var(--mgr-invoices-ink) 9%, transparent);
  box-shadow: 0 1px 0 oklch(1 0 0 / .8) inset, 0 22px 44px -26px oklch(0.25 0.06 45 / .55);
  font: 400 13px/1.35 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--mgr-invoices-accent); outline-offset: 2px; border-radius: 6px; }

  & .mgr-invoices-head {
    display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; margin-bottom: 12px;
  }
  & .mgr-invoices-head > div:first-child { min-width: 0; }
  & .mgr-invoices-head > :last-child { flex: none; }
  & .mgr-invoices-eyebrow { white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    margin: 0 0 3px; font-size: clamp(9.5px, 2.9cqi, 10.5px); font-weight: 600; letter-spacing: .1em;
    text-transform: uppercase; color: var(--mgr-invoices-dim);
  }
  & .mgr-invoices-h {
    margin: 0; font-size: clamp(18px, 6.6cqi, 24px); font-weight: 680; letter-spacing: -.025em; line-height: 1;
    text-wrap: balance;
  }
  & .mgr-invoices-kpi { display: grid; justify-items: end; gap: 2px; text-align: right; }
  & .mgr-invoices-kpi-v {
    font-size: clamp(15px, 5cqi, 18px); font-weight: 650; letter-spacing: -.02em;
    font-variant-numeric: tabular-nums;
  }
  & .mgr-invoices-kpi-l { font-size: 10.5px; color: var(--mgr-invoices-dim); white-space: nowrap; }
  & .mgr-invoices-kpi-l b { color: var(--mgr-invoices-accent); font-weight: 600; }

  /* status filter: radiogroup with a sliding pill measured by JS */
  & .mgr-invoices-chips {
    position: relative; display: flex; gap: 2px; padding: 3px; margin-bottom: 8px;
    background: var(--mgr-invoices-wash); border: 1px solid var(--mgr-invoices-line); border-radius: 10px;
    overflow-x: auto; scrollbar-width: none;
    &::-webkit-scrollbar { display: none; }
  }
  & .mgr-invoices-ind {
    position: absolute; left: 0; top: 3px; bottom: 3px; width: var(--w, 40px);
    translate: var(--x, 3px) 0; border-radius: 7px;
    background: var(--mgr-invoices-paper);
    box-shadow: 0 1px 2px oklch(0.3 0.04 50 / .14), 0 0 0 1px var(--mgr-invoices-line);
    transition: translate .55s var(--mgr-invoices-spring), width .55s var(--mgr-invoices-spring);
  }
  & .mgr-invoices-chips button {
    position: relative; flex: 1 0 auto; display: inline-flex; align-items: center; justify-content: center; gap: 5px;
    border: 0; background: none; padding: 5px 8px; border-radius: 7px;
    font-size: 12px; font-weight: 550; color: var(--mgr-invoices-dim);
    transition: color .2s;
    &:hover { color: var(--mgr-invoices-ink); }
    &[aria-checked="true"] { color: var(--mgr-invoices-ink); }
    & i {
      font-style: normal; font-size: 10px; font-weight: 600; font-variant-numeric: tabular-nums;
      min-width: 15px; padding: 1px 4px; border-radius: 99px;
      background: color-mix(in oklch, var(--mgr-invoices-ink) 8%, transparent);
    }
    &[data-f="overdue"] i { background: color-mix(in oklch, var(--mgr-invoices-accent) 16%, transparent); color: var(--mgr-invoices-accent); }
  }

  & .mgr-invoices-search {
    display: flex; align-items: center; gap: 7px; height: 32px; padding: 0 8px 0 9px; margin-bottom: 6px;
    border: 1px solid var(--mgr-invoices-line); border-radius: 9px; background: oklch(1 0 0 / .6);
    transition: border-color .2s, box-shadow .2s;
    &:focus-within {
      border-color: color-mix(in oklch, var(--mgr-invoices-accent) 55%, transparent);
      box-shadow: 0 0 0 3px color-mix(in oklch, var(--mgr-invoices-accent) 14%, transparent);
    }
    & svg { width: 14px; height: 14px; flex: none; fill: none; stroke: var(--mgr-invoices-dim); stroke-width: 1.5; stroke-linecap: round; }
    & input {
      flex: 1; min-width: 0; border: 0; background: none; outline: none; font-size: 12.5px;
      &::placeholder { color: var(--mgr-invoices-dim); }
      &::-webkit-search-cancel-button { filter: grayscale(1); opacity: .5; }
    }
    & kbd {
      font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 3px 5px; border-radius: 4px;
      border: 1px solid var(--mgr-invoices-line); color: var(--mgr-invoices-dim);
    }
    &:focus-within kbd { opacity: 0; }
  }

  /* one grid, every row a subgrid: columns size to content once, for all rows */
  & .mgr-invoices-table {
    display: grid; grid-template-columns: minmax(0, 1fr) auto auto auto;
    column-gap: clamp(8px, 3.4cqi, 14px);
  }
  & .mgr-invoices-row, & .mgr-invoices-body {
    display: grid; grid-column: 1 / -1; grid-template-columns: subgrid; align-items: center;
  }
  & .mgr-invoices-body { row-gap: 0; }
  & .mgr-invoices-row {
    position: relative; min-height: 36px; padding-block: 3px;
    border-top: 1px solid var(--mgr-invoices-line);
    view-transition-class: mgr-invoices-row;
    &[hidden] { display: none; }
  }
  & .mgr-invoices-body > .mgr-invoices-row:hover { background: linear-gradient(90deg, transparent, var(--mgr-invoices-wash) 12%, var(--mgr-invoices-wash) 88%, transparent); }
  & .mgr-invoices-hrow { min-height: 28px; padding-block: 0; border-top: 0; }
  & .mgr-invoices-th button {
    display: inline-flex; align-items: center; gap: 3px; border: 0; background: none; padding: 4px 0;
    font-size: 10px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--mgr-invoices-dim);
    &:hover { color: var(--mgr-invoices-ink); }
    & svg {
      width: 11px; height: 11px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round;
      opacity: 0; scale: .6; transition: opacity .2s, scale .35s var(--mgr-invoices-spring), rotate .45s var(--mgr-invoices-spring);
    }
    &:hover svg { opacity: .45; scale: 1; }
  }
  & .mgr-invoices-th.is-num { justify-self: end; & button { flex-direction: row-reverse; } }
  & .mgr-invoices-th[aria-sort="ascending"], & .mgr-invoices-th[aria-sort="descending"] {
    & button { color: var(--mgr-invoices-ink); }
    & svg { opacity: 1; scale: 1; color: var(--mgr-invoices-accent); }
  }
  & .mgr-invoices-th[aria-sort="ascending"] svg { rotate: 180deg; }

  & .mgr-invoices-client {
    min-width: 0; display: grid; gap: 1px; padding-left: 9px; position: relative;
    & b { font-weight: 600; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & small { font-size: 10.5px; color: var(--mgr-invoices-dim); white-space: nowrap; }
    &::before {
      content: ""; position: absolute; left: 0; top: 3px; bottom: 3px; width: 2px; border-radius: 2px;
      background: transparent;
    }
  }
  & .mgr-invoices-no { font-family: ui-monospace, Menlo, monospace; font-size: 10px; letter-spacing: .02em; }
  & .mgr-invoices-due-inline { display: none; }
  & .mgr-invoices-row[data-status="overdue"] .mgr-invoices-client::before { background: var(--mgr-invoices-accent); }
  & .mgr-invoices-due {
    display: grid; gap: 1px; font-variant-numeric: tabular-nums;
    & time { font-size: 12px; }
    & small { font-size: 10px; color: var(--mgr-invoices-dim); white-space: nowrap; }
  }
  & .mgr-invoices-row[data-status="overdue"] .mgr-invoices-due small { color: var(--mgr-invoices-accent); font-weight: 550; }
  & .mgr-invoices-pill {
    display: inline-flex; align-items: center; gap: 5px; padding: 2px 8px 2px 7px; border-radius: 99px;
    font-size: 10.5px; font-weight: 600; white-space: nowrap;
    &::before { content: ""; width: 5px; height: 5px; border-radius: 50%; background: currentColor; }
    &[data-s="paid"] { color: color-mix(in oklch, var(--mgr-invoices-ok), var(--mgr-invoices-ink) 25%); background: color-mix(in oklch, var(--mgr-invoices-ok) 13%, transparent); }
    &[data-s="overdue"] { color: var(--mgr-invoices-accent); background: color-mix(in oklch, var(--mgr-invoices-accent) 12%, transparent); }
    &[data-s="open"] { color: var(--mgr-invoices-ink); box-shadow: inset 0 0 0 1px var(--mgr-invoices-line); }
    &[data-s="draft"] { color: var(--mgr-invoices-dim); box-shadow: inset 0 0 0 1px var(--mgr-invoices-line); &::before { background: none; box-shadow: inset 0 0 0 1px currentColor; } }
  }
  & .mgr-invoices-amt { justify-self: end; font-weight: 600; font-size: 12.5px; font-variant-numeric: tabular-nums; letter-spacing: -.01em; }
  & .mgr-invoices-row[data-status="paid"] .mgr-invoices-amt { color: var(--mgr-invoices-dim); font-weight: 500; }

  & .mgr-invoices-empty {
    display: grid; justify-items: center; gap: 8px; padding: 22px 8px 18px; text-align: center;
    border-top: 1px solid var(--mgr-invoices-line);
    &[hidden] { display: none; }
    animation: mgr-invoices-rise .5s var(--mgr-invoices-ease) both;
    & svg { width: 44px; height: 44px; fill: none; stroke: var(--mgr-invoices-dim); stroke-width: 1.4; stroke-linecap: round; stroke-linejoin: round; }
    & p { margin: 0; display: grid; gap: 2px; text-wrap: pretty; }
    & b { font-weight: 650; }
    & span { font-size: 11.5px; color: var(--mgr-invoices-dim); }
    & button {
      border: 1px solid var(--mgr-invoices-line); background: var(--mgr-invoices-paper); border-radius: 8px;
      padding: 6px 12px; font-size: 12px; font-weight: 600;
      &:hover { border-color: color-mix(in oklch, var(--mgr-invoices-ink) 30%, transparent); }
    }
  }
  & .mgr-invoices-foot {
    display: flex; justify-content: space-between; gap: 8px; padding-top: 9px; margin-top: 2px;
    border-top: 1px solid color-mix(in oklch, var(--mgr-invoices-ink) 22%, transparent);
    font-size: 11px; color: var(--mgr-invoices-dim); font-variant-numeric: tabular-nums;
    & b { color: var(--mgr-invoices-ink); font-weight: 650; font-size: 12.5px; margin-left: 4px; }
  }

  @container (width < 340px) {
    & .mgr-invoices-table { grid-template-columns: minmax(0, 1fr) auto auto; }
    & .mgr-invoices-due { display: none; }
    & .mgr-invoices-due-inline { display: inline; }
    & .mgr-invoices-chips i { display: none; }
  }
}
@supports not (grid-template-columns: subgrid) {
  .mgr-invoices .mgr-invoices-row { grid-template-columns: minmax(0, 1fr) 62px 72px 82px; column-gap: 10px; }
}
@keyframes mgr-invoices-rise { from { opacity: 0; translate: 0 8px; filter: blur(3px); } }

/* sort and filter run inside a document view transition; rows carry a class so their
   groups get a spring and the cross-fade stays short */
::view-transition-group(*.mgr-invoices-row) { animation-duration: .6s; animation-timing-function: linear(0, 0.0174 2%, 0.0635 4%, 0.168 7%, 0.296 10%, 0.474 14%, 0.638 18%, 0.805 23%, 0.922 28%, 1 34%, 1.04 40%, 1.05 46%, 1.04 53%, 1.02 60%, 1.01 70%, 0.999 80%, 1); }
::view-transition-old(*.mgr-invoices-row), ::view-transition-new(*.mgr-invoices-row) { animation-duration: .22s; }

@media (prefers-reduced-motion: reduce) {
  .mgr-invoices {
    & .mgr-invoices-ind, & .mgr-invoices-th svg { transition: opacity .2s linear; }
    & .mgr-invoices-empty { animation: mgr-invoices-fade .2s linear both; }
  }
}
@keyframes mgr-invoices-fade { from { opacity: 0; } }

js:
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = 'linear(0, 0.0174 2%, 0.0635 4%, 0.168 7%, 0.296 10%, 0.474 14%, 0.638 18%, 0.805 23%, 0.922 28%, 1 34%, 1.04 40%, 1.05 46%, 1.04 53%, 1.02 60%, 1.01 70%, 0.999 80%, 1)';
const $ = s => root.querySelector(s);
const $$ = s => [...root.querySelectorAll(s)];
const uid = Math.random().toString(36).slice(2, 7);
const body = $('.mgr-invoices-body');
const empty = $('.mgr-invoices-empty');
const why = $('[data-why]');
const shown = $('[data-shown]');
const totalEl = $('[data-total]');
const input = $('.mgr-invoices-search input');
const chipsWrap = $('.mgr-invoices-chips');
const ind = $('.mgr-invoices-ind');
const chips = $$('.mgr-invoices-chips [role="radio"]');
const heads = $$('.mgr-invoices-th');
const fmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
const RANK = { overdue: 0, open: 1, draft: 2, paid: 3 };
const data = $$('.mgr-invoices-body > .mgr-invoices-row').map((el, i) => ({
  el, i, id: el.dataset.id, client: el.dataset.client, due: el.dataset.due,
  status: el.dataset.status, amount: +el.dataset.amount,
  hay: (el.dataset.client + ' inv-' + el.dataset.id + ' ' + el.dataset.id).toLowerCase()
}));
const state = { f: 'all', q: '', key: null, dir: 0 };

/* counts come from the rows, never from hand-typed markup */
const count = k => data.filter(d => k === 'all' || d.status === k).length;
$$('[data-n]').forEach(n => { n.textContent = count(n.dataset.n); });
$('[data-out]').textContent = fmt.format(data.filter(d => d.status === 'open' || d.status === 'overdue').reduce((a, d) => a + d.amount, 0));

const cmp = (a, b) => {
  const k = state.key; let r;
  if (k === 'amount') r = a.amount - b.amount;
  else if (k === 'status') r = RANK[a.status] - RANK[b.status] || a.due.localeCompare(b.due);
  else if (k === 'due') r = a.due.localeCompare(b.due);
  else r = a.client.localeCompare(b.client);
  return r * state.dir || a.i - b.i;
};

let tv = data.reduce((a, d) => a + d.amount, 0), raf = 0;
function tween(to) {
  const from = tv, t0 = performance.now(), dur = RM.matches ? 0 : 560;
  cancelAnimationFrame(raf);
  const step = now => {
    if (!root.isConnected) return;
    const k = dur ? Math.min(1, (now - t0) / dur) : 1;
    tv = from + (to - from) * (1 - Math.pow(1 - k, 4));
    totalEl.textContent = fmt.format(k === 1 ? to : tv);
    if (k < 1) raf = requestAnimationFrame(step);
  };
  raf = requestAnimationFrame(step);
}

function apply() {
  const vis = new Set(data.filter(d => (state.f === 'all' || d.status === state.f) && (!state.q || d.hay.includes(state.q))));
  const order = state.dir ? [...data].sort(cmp) : data;
  order.forEach(d => { body.appendChild(d.el); d.el.hidden = !vis.has(d); });
  heads.forEach(h => h.setAttribute('aria-sort', h.dataset.k === state.key && state.dir ? (state.dir > 0 ? 'ascending' : 'descending') : 'none'));
  chips.forEach(c => { const on = c.dataset.f === state.f; c.setAttribute('aria-checked', on); c.tabIndex = on ? 0 : -1; });
  empty.hidden = vis.size > 0;
  if (!vis.size) why.textContent = state.q ? 'Nothing for “' + input.value.trim() + '”' + (state.f !== 'all' ? ' in ' + state.f + '.' : '.') : 'No ' + state.f + ' invoices right now.';
  shown.textContent = vis.size + ' of ' + data.length + ' invoices';
  tween([...vis].reduce((a, d) => a + d.amount, 0));
  moveInd(false);
}

/* FLIP: read every row, mutate once, read again, then hand the deltas to WAAPI */
function flip(mutate) {
  const before = new Map(data.map(d => [d, d.el.hidden ? null : d.el.getBoundingClientRect().top]));
  mutate();
  if (RM.matches) return;
  const after = data.map(d => [d, d.el.hidden ? null : d.el.getBoundingClientRect().top]);
  after.forEach(([d, top]) => {
    if (top == null) return;
    const was = before.get(d);
    if (was == null) d.el.animate([{ opacity: 0, transform: 'translateY(6px)' }, { opacity: 1, transform: 'none' }], { duration: 260, easing: 'cubic-bezier(.2,.8,.2,1)' });
    else if (Math.abs(was - top) > 0.5) d.el.animate([{ transform: 'translateY(' + (was - top) + 'px)' }, { transform: 'none' }], { duration: 620, easing: SPRING });
  });
}

/* sort and status changes morph rows with a view transition; typing uses FLIP so the
   input never sits behind a frozen snapshot */
let vtSeq = 0;
function morph(mutate) {
  if (RM.matches) return mutate();
  if (!document.startViewTransition) return flip(mutate);
  const my = ++vtSeq;
  data.forEach(d => { d.el.style.viewTransitionName = 'mgr-invoices-' + uid + '-' + d.id; });
  const vt = document.startViewTransition(mutate);
  /* a rapid second change skips the first transition: that rejection is expected, and only
     the latest transition may clear the names the next capture depends on */
  vt.ready.catch(() => {});
  vt.finished.finally(() => { if (my === vtSeq) data.forEach(d => { d.el.style.viewTransitionName = ''; }); });
}

function moveInd(instant) {
  const b = chips.find(c => c.dataset.f === state.f);
  if (!b) return;
  if (instant) ind.style.transition = 'none';
  ind.style.setProperty('--x', b.offsetLeft + 'px');
  ind.style.setProperty('--w', b.offsetWidth + 'px');
  if (instant) { ind.offsetWidth; ind.style.transition = ''; }
}
const ro = new ResizeObserver(() => { if (!root.isConnected) return ro.disconnect(); moveInd(true); });
ro.observe(chipsWrap);

heads.forEach(h => h.querySelector('button').addEventListener('click', () => {
  const k = h.dataset.k, first = k === 'amount' ? -1 : 1;
  if (state.key !== k) { state.key = k; state.dir = first; }
  else if (state.dir === first) state.dir = -first;
  else { state.key = null; state.dir = 0; }
  morph(apply);
}));

function pick(f, focus) {
  if (f === state.f) return;
  state.f = f;
  morph(apply);
  if (focus) chips.find(c => c.dataset.f === f).focus();
}
chipsWrap.addEventListener('click', e => { const b = e.target.closest('[role="radio"]'); if (b) pick(b.dataset.f); });
chipsWrap.addEventListener('keydown', e => {
  const i = chips.findIndex(c => c.dataset.f === state.f);
  let j = -1;
  if (e.key === 'ArrowRight' || e.key === 'ArrowDown') j = (i + 1) % chips.length;
  else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') j = (i - 1 + chips.length) % chips.length;
  else if (e.key === 'Home') j = 0;
  else if (e.key === 'End') j = chips.length - 1;
  if (j < 0) return;
  e.preventDefault(); pick(chips[j].dataset.f, true);
});

input.addEventListener('input', () => { state.q = input.value.trim().toLowerCase(); flip(apply); });
input.addEventListener('keydown', e => { if (e.key === 'Escape' && input.value) { e.stopPropagation(); input.value = ''; state.q = ''; flip(apply); } });
root.addEventListener('keydown', e => {
  if (e.key === '/' && e.target !== input && !e.metaKey && !e.ctrlKey) { e.preventDefault(); input.focus(); input.select(); }
});
$('[data-clear]').addEventListener('click', () => {
  input.value = ''; state.q = ''; state.f = 'all';
  morph(apply); chips[0].focus();
});
moveInd(true);

css:
.mgr-stream {
  --mgr-stream-bg: oklch(0.185 0.006 95);
  --mgr-stream-ink: oklch(0.93 0.012 95);
  --mgr-stream-accent: oklch(0.9 0.19 126);
  --mgr-stream-warn: oklch(0.8 0.15 74);
  --mgr-stream-err: oklch(0.68 0.2 24);
  --mgr-stream-row: 26px;
  --mgr-stream-line: color-mix(in oklch, var(--mgr-stream-ink) 9%, transparent);
  --mgr-stream-dim: color-mix(in oklch, var(--mgr-stream-ink) 50%, var(--mgr-stream-bg));
  --mgr-stream-raise: color-mix(in oklch, var(--mgr-stream-ink) 5%, var(--mgr-stream-bg));
  --mgr-stream-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  container-type: inline-size;
  box-sizing: border-box; width: 100%; max-width: 480px; margin-inline: auto;
  padding: 14px 12px 10px; border-radius: 14px;
  background:
    radial-gradient(120% 60% at 100% 0%, color-mix(in oklch, var(--mgr-stream-accent) 7%, transparent), transparent 60%),
    var(--mgr-stream-bg);
  color: var(--mgr-stream-ink);
  border: 1px solid var(--mgr-stream-line);
  font: 400 12px/1.35 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  timeline-scope: --mgr-stream-y;
  & *, & *::before, & *::after { box-sizing: border-box; }
