const SDT = typeof CSS !== 'undefined' && CSS.supports('animation-timeline: scroll()');
const nf = new Intl.NumberFormat('en-US');

/* ---- data: 10,000 rows in typed arrays, generated in slices so the UI paints a progress state ---- */
