const PATHS = [
  ['/api/v2/orders', 60], ['/api/v2/cart', 45], ['/api/v2/search?q=linen', 70], ['/auth/session', 30],
  ['/img/hero-1280.avif', 9], ['/img/thumb/48213.webp', 6], ['/assets/app.4f1c9e.js', 5], ['/assets/app.77b2.css', 4],
  ['/fonts/sans-var.woff2', 4], ['/healthz', 2], ['/api/v2/checkout', 180], ['/api/v2/inventory/sku-2210', 55]
