let clock = (14 * 3600 + 2 * 60) * 1000;
function gen(from, to) {
  for (let i = from; i < to; i++) {
    clock += -Math.log(rnd() + 1e-9) * 36;
    t[i] = clock;
    const p = Math.floor(Math.pow(rnd(), 1.35) * PATHS.length);
    path[i] = p;
    const r = rnd();
    /* static assets and the health check are GET-only; writes cluster on checkout and session */
    meth[i] = (p >= 4 && p <= 9) ? 0 : p === 10 || p === 3 ? (r < .7 ? 1 : r < .8 ? 3 : 0) : r < .9 ? 0 : r < .95 ? 2 : r < .975 ? 1 : 3;
