const pad = (v, l) => String(v).padStart(l, '0');
const fmtT = ms => { const s = Math.floor(ms / 1000); return pad(Math.floor(s / 3600), 2) + ':' + pad(Math.floor(s / 60) % 60, 2) + ':' + pad(s % 60, 2) + '.' + pad(Math.floor(ms % 1000), 3); };
