const lmax = Math.log(4000);

function makeRow() {
  const r = document.createElement('div');
  r.className = 'mgr-stream-row'; r.setAttribute('role', 'row'); r.hidden = true;
  r.innerHTML = '<span role="gridcell" class="mgr-stream-i"></span><span role="gridcell" class="mgr-stream-t"></span>' +
    '<span role="gridcell" class="mgr-stream-p"><b class="mgr-stream-m"></b><span class="mgr-stream-u"></span></span>' +
    '<span role="gridcell" class="mgr-stream-s"></span><span role="gridcell" class="mgr-stream-l"><span></span><i></i></span>';
