  r._m.textContent = meth[i] === 3 ? 'DEL' : METHODS[meth[i]]; r._m.dataset.m = METHODS[meth[i]];
  r._u.textContent = PATHS[path[i]][0];
  r._s.textContent = code[i]; r._s.dataset.c = cls(code[i]);
  r._lv.textContent = lat[i] >= 1000 ? (lat[i] / 1000).toFixed(1) + 's' : lat[i];
