  domEl.textContent = pool.filter(r => !r.hidden).length;
  rangeEl.textContent = n ? nf.format(a) + '–' + nf.format(b) + ' of ' + nf.format(n) : '0 of 0';
  if (!SDT) {
    const max = Math.max(1, grid.scrollHeight - grid.clientHeight);
