};
grid.addEventListener('scroll', schedule, { passive: true });

/* ---- overview strip: DPR-aware canvas, redrawn on resize and on filter change ---- */
const ctx = canvas.getContext('2d');
function color(v, fb) { ctx.fillStyle = fb; ctx.fillStyle = v || fb; return ctx.fillStyle; }
function drawMap() {
  if (!ctx || !ready) return;
