  const w = track.clientWidth, h = track.clientHeight;
  if (!w || !h) return;
  canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr);
  const cs = getComputedStyle(root);
  const warn = color(cs.getPropertyValue('--mgr-stream-warn').trim(), '#e8b54a');
  const err = color(cs.getPropertyValue('--mgr-stream-err').trim(), '#e5534b');
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  const H = canvas.height, W = canvas.width;
  for (let y = 0; y < H; y++) {
    const a = Math.floor(y / H * n), b = Math.max(a + 1, Math.floor((y + 1) / H * n));
    let w4 = 0, w5 = 0;
    for (let k = a; k < b && k < n; k++) { const c = code[index ? index[k] : k]; if (c >= 500) w5++; else if (c >= 400) w4++; }
    const sz = b - a;
