const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = 'linear(0, 0.0174 2%, 0.0635 4%, 0.168 7%, 0.296 10%, 0.474 14%, 0.638 18%, 0.805 23%, 0.922 28%, 1 34%, 1.04 40%, 1.05 46%, 1.04 53%, 1.02 60%, 1.01 70%, 0.999 80%, 1)';
const $ = s => root.querySelector(s), $$ = s => [...root.querySelectorAll(s)];
const grid = $('.mgr-columns-grid'), scroller = $('.mgr-columns-scroll'), ghost = $('.mgr-columns-ghost');
const live = $('.mgr-columns-live'), resetBtn = $('[data-reset]');
const COLS = {
  crop: { label: 'Crop', base: 112, min: 84, max: 220, locked: true },
  bed: { label: 'Bed', base: 46, min: 38, max: 120 },
  germ: { label: 'Germination', base: 92, min: 60, max: 200 },
  yield: { label: 'Yield', base: 70, min: 56, max: 140 }
};
const DEFAULT = ['crop', 'bed', 'germ', 'yield'];
let order = DEFAULT.slice(), customW = false;
const rows = $$('.mgr-columns-row').map(row => {
  const m = {}; row.querySelectorAll(':scope > [data-col]').forEach(c => { m[c.dataset.col] = c; }); return { row, m };
});
const colCells = k => rows.map(r => r.m[k]);
const handles = {}; $$('.mgr-columns-handle').forEach(h => { handles[h.dataset.h] = h; });

const say = msg => { live.textContent = ''; live.textContent = msg; };
const left = k => { let x = 0; for (const c of order) { if (c === k) return x; x += COLS[c].w; } return x; };
const total = () => order.reduce((a, k) => a + COLS[k].w, 0);
const isDefault = () => order.join() === DEFAULT.join() && !customW;

function setTracks(tween) {
  grid.classList.toggle('is-tween', !!tween && !RM.matches);
  grid.style.setProperty('--mgr-columns-tracks', order.map(k => COLS[k].w + 'px').join(' '));
  for (const k of order) {
    const h = handles[k], c = COLS[k];
    h.setAttribute('aria-valuenow', c.w); h.setAttribute('aria-valuemin', c.min); h.setAttribute('aria-valuemax', c.max);
    h.setAttribute('aria-valuetext', c.w + ' pixels');
    h.firstChild.textContent = c.w + ' px';
  }
