}
/* defaults scale to the space the component is given, within each column's limits */
function fit() {
  const avail = scroller.clientWidth - 2;
  const sum = DEFAULT.reduce((a, k) => a + COLS[k].base, 0);
  const f = avail / sum;
  for (const k of DEFAULT) COLS[k].w = Math.round(Math.max(COLS[k].min, Math.min(COLS[k].max, COLS[k].base * f)));
}

/* reorder real DOM so tab order and aria-colindex follow what is on screen. The pivot
   cell never moves, so a focused grip or a captured pointer stays put; moveBefore()
   keeps state where it exists */
function arrange(pivotKey) {
  const p = order.indexOf(pivotKey);
  for (const { row, m } of rows) {
    const put = (c, ref) => {
      if (c.nextSibling === ref) return;
      if (row.moveBefore) { try { row.moveBefore(c, ref); return; } catch (_) { /* fall through */ } }
      row.insertBefore(c, ref);
    };
    let ref = m[pivotKey];
    for (let j = p - 1; j >= 0; j--) { const c = m[order[j]]; put(c, ref); ref = c; }
    let prev = m[pivotKey];
    for (let j = p + 1; j < order.length; j++) { const c = m[order[j]]; put(c, prev.nextSibling); prev = c; }
    order.forEach((k, i) => m[k].setAttribute('aria-colindex', i + 1));
  }
}
function reorder(next, pivotKey, skipAnim) {
  const before = {}; order.forEach(k => { before[k] = left(k); });
  order = next; arrange(pivotKey); setTracks(false);
  if (RM.matches) return;
  for (const k of order) {
    if (k === skipAnim) continue;
    const d = before[k] - left(k);
    if (d) colCells(k).forEach(c => c.animate([{ transform: 'translateX(' + d + 'px)' }, { transform: 'none' }], { duration: 560, easing: SPRING }));
  }
}
function moveBy(k, step) {
  const i = order.indexOf(k), j = Math.max(1, Math.min(order.length - 1, i + step));
  if (i === j) return;
  const next = order.filter(c => c !== k); next.splice(j, 0, k);
  reorder(next, k);
  say(COLS[k].label + ' moved to column ' + (j + 1) + ' of ' + order.length);
