/* ---- drag to reorder: pointer capture on the grip, one custom property moves the column ---- */
let drag = null;
grid.addEventListener('pointerdown', e => {
  const grip = e.target.closest('button.mgr-columns-grip');
  if (!grip || e.button !== 0) return;
  const k = grip.parentElement.dataset.col;
  drag = { k, grip, id: e.pointerId, x0: e.clientX, l0: left(k), on: false, L: left(k) };
  grip.setPointerCapture(e.pointerId);
});
grid.addEventListener('pointermove', e => {
  if (!drag || e.pointerId !== drag.id) return;
  const dx = e.clientX - drag.x0;
  if (!drag.on) {
    if (Math.abs(dx) < 4) return;
    drag.on = true;
    colCells(drag.k).forEach(c => c.classList.add('is-drag'));
    ghost.style.setProperty('--gw', COLS[drag.k].w + 'px');
    root.classList.add('is-dragging');
  }
  const w = COLS[drag.k].w;
  const L = Math.max(COLS.crop.w, Math.min(total() - w, drag.l0 + dx));
  const center = L + w / 2, rest = order.filter(c => c !== drag.k);
  let acc = 0, idx = rest.length;
  for (let i = 0; i < rest.length; i++) { if (center < acc + COLS[rest[i]].w / 2) { idx = i; break; } acc += COLS[rest[i]].w; }
  idx = Math.max(1, idx);
  const next = rest.slice(); next.splice(idx, 0, drag.k);
  if (next.join() !== order.join()) reorder(next, drag.k, drag.k);
  drag.L = L;
  root.style.setProperty('--mgr-columns-dx', (L - left(drag.k)) + 'px');
  ghost.style.setProperty('--gx', L + 'px');
});
function endDrag(e) {
  if (!drag || (e && e.pointerId !== drag.id)) return;
  const d = drag;
  drag = null;
  if (!d.on) return;
  const off = d.L - left(d.k);
  colCells(d.k).forEach(c => c.classList.remove('is-drag'));
  root.style.setProperty('--mgr-columns-dx', '0px');
  root.classList.remove('is-dragging');
  if (!RM.matches && off) colCells(d.k).forEach(c => c.animate([{ transform: 'translateX(' + off + 'px)' }, { transform: 'none' }], { duration: 480, easing: SPRING }));
  setTracks(false);
  say(COLS[d.k].label + ' moved to column ' + (order.indexOf(d.k) + 1) + ' of ' + order.length);
}
grid.addEventListener('pointerup', endDrag);
grid.addEventListener('pointercancel', endDrag);
grid.addEventListener('lostpointercapture', endDrag);
grid.addEventListener('keydown', e => {
  const grip = e.target.closest('button.mgr-columns-grip');
  if (grip && e.altKey && (e.key === 'ArrowLeft' || e.key === 'ArrowRight')) {
    e.preventDefault(); moveBy(grip.parentElement.dataset.col, e.key === 'ArrowLeft' ? -1 : 1);
    if (document.activeElement !== grip) grip.focus();
  }
});

/* ---- resize: separators with pointer capture, arrow keys and auto-fit ---- */
let rs = null;
function setW(k, w, tween) {
  const c = COLS[k];
  c.w = Math.round(Math.max(c.min, Math.min(c.max, w)));
  customW = true; setTracks(tween);
}
function autoFit(k) {
  root.classList.add('is-measuring');
  const widths = colCells(k).map(c => c.firstElementChild.getBoundingClientRect().width);
  root.classList.remove('is-measuring');
  setW(k, Math.ceil(Math.max(...widths)) + 22, true);
  say(COLS[k].label + ' fitted to ' + COLS[k].w + ' pixels');
}
Object.entries(handles).forEach(([k, h]) => {
  h.addEventListener('pointerdown', e => {
    if (e.button !== 0) return;
    e.preventDefault();
    rs = { k, id: e.pointerId, x0: e.clientX, w0: COLS[k].w };
    h.setPointerCapture(e.pointerId); h.classList.add('is-active');
  });
  h.addEventListener('pointermove', e => { if (rs && rs.id === e.pointerId) setW(k, rs.w0 + e.clientX - rs.x0, false); });
  const stop = e => { if (!rs || rs.id !== e.pointerId) return; rs = null; h.classList.remove('is-active'); say(COLS[k].label + ' is ' + COLS[k].w + ' pixels wide'); };
  h.addEventListener('pointerup', stop); h.addEventListener('pointercancel', stop);
  h.addEventListener('dblclick', () => autoFit(k));
  h.addEventListener('keydown', e => {
    const step = e.shiftKey ? 32 : 8, c = COLS[k];
    const to = { ArrowLeft: c.w - step, ArrowRight: c.w + step, Home: c.min, End: c.max }[e.key];
    if (to != null) { e.preventDefault(); setW(k, to, true); }
    else if (e.key === 'Enter') { e.preventDefault(); autoFit(k); }
  });
});

resetBtn.addEventListener('click', () => {
  const moved = order.join() !== DEFAULT.join();
  customW = false; fit();
  if (moved) reorder(DEFAULT.slice(), 'crop');
  setTracks(!moved);
  say('Layout reset');
  scroller.scrollTo({ left: 0, behavior: RM.matches ? 'auto' : 'smooth' });
});

const ro = new ResizeObserver(() => {
  if (!root.isConnected) return ro.disconnect();
  if (!customW) { fit(); setTracks(false); }
});
ro.observe(scroller);
fit(); setTracks(false);

