  & .mgr-bulk-av {
    flex: none; display: grid; place-items: center; width: 26px; height: 26px; border-radius: 8px;
    font: 700 9.5px/1 system-ui, sans-serif; font-style: normal; letter-spacing: .02em;
    background: oklch(0.42 0.07 var(--h)); color: oklch(0.93 0.05 var(--h));
