  }
  & .mgr-bulk-plan { flex: none; }
  & .mgr-bulk-st { min-width: 0; overflow: hidden; text-overflow: ellipsis; display: inline-flex; align-items: center; gap: 4px; }
  & .mgr-bulk-plan::after { content: "\00b7"; margin-left: 5px; }
  & .mgr-bulk-row[data-status="paused"] {
    & .mgr-bulk-st { color: var(--mgr-bulk-ink); }
    & .mgr-bulk-st::before { content: ""; width: 6px; height: 6px; border-radius: 2px; box-shadow: inset 2px 0 0 currentColor, inset -2px 0 0 currentColor; }
    & .mgr-bulk-mrr { color: var(--mgr-bulk-dim); text-decoration: line-through; text-decoration-color: color-mix(in oklch, var(--mgr-bulk-ink) 35%, transparent); }
  }
  & .mgr-bulk-row[data-status="hold"] .mgr-bulk-st { color: var(--mgr-bulk-accent); }
  & .mgr-bulk-row.is-pending .mgr-bulk-st {
    color: var(--mgr-bulk-ink);
    &::before { content: ""; width: 9px; height: 9px; border-radius: 50%; border: 1.5px solid currentColor; border-right-color: transparent; box-shadow: none; animation: mgr-bulk-spin .7s linear infinite; }
  }
  & .mgr-bulk-mrr { font-weight: 600; }

  /* bulk toolbar slides over the header, leaving the select-all checkbox live */
  & .mgr-bulk-bar {
    position: absolute; z-index: 3; top: 1px; left: 33px; right: 1px; height: 33px;
    display: flex; align-items: center; gap: 4px; padding: 0 5px 0 4px; border-radius: 0 9px 0 0;
    background: color-mix(in oklch, var(--mgr-bulk-accent) 16%, var(--mgr-bulk-bg));
    clip-path: inset(0 100% 0 0); opacity: 0;
    transition: clip-path .5s var(--mgr-bulk-ease), opacity .2s;
    &.is-open { clip-path: inset(0 0 0 0); opacity: 1; }
    & button {
      display: inline-flex; align-items: center; gap: 5px; height: 25px; padding: 0 7px; border-radius: 7px;
      border: 1px solid transparent; background: none; font-size: 11.5px; font-weight: 600; white-space: nowrap;
      transition: background .2s, border-color .2s, color .2s;
      &:hover { background: color-mix(in oklch, var(--mgr-bulk-ink) 9%, transparent); }
      & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
      & span { display: none; }
      &.is-danger { color: var(--mgr-bulk-danger); &:hover { background: color-mix(in oklch, var(--mgr-bulk-danger) 16%, transparent); } }
    }
    & [data-act="pause"] svg:nth-of-type(2) { display: none; fill: currentColor; stroke: none; }
    & [data-act="pause"].is-resume { & svg:nth-of-type(1) { display: none; } & svg:nth-of-type(2) { display: block; } }
