    & svg { width: 38px; height: 38px; margin-bottom: 4px; fill: none; stroke: var(--mgr-bulk-dim); stroke-width: 1.5; stroke-linecap: round; }
    & b { font-weight: 650; }
    & span { font-size: 11.5px; color: var(--mgr-bulk-dim); }
    & button { margin-top: 8px; height: 28px; padding: 0 12px; border-radius: 8px; border: 1px solid var(--mgr-bulk-line); background: var(--mgr-bulk-raise); font-weight: 600; font-size: 12px; }
  }
  &.is-empty .mgr-bulk-grid { display: none; }

  & .mgr-bulk-foot {
    display: flex; justify-content: space-between; gap: 8px; margin-top: 8px; font-size: 10.5px; color: var(--mgr-bulk-dim);
    & kbd { display: inline-block; padding: 0 4px; border-radius: 4px; border: 1px solid var(--mgr-bulk-line); font: 600 9.5px/15px ui-monospace, Menlo, monospace; color: var(--mgr-bulk-ink); }
  }
  & .mgr-bulk-keys { white-space: nowrap; }

  & .mgr-bulk-toast {
    position: absolute; left: 12px; right: 12px; bottom: 10px; z-index: 5; overflow: hidden;
    display: flex; align-items: center; gap: 10px; padding: 9px 10px 9px 12px; border-radius: 11px;
    background: var(--mgr-bulk-ink); color: var(--mgr-bulk-bg); font-size: 12px; font-weight: 550;
    box-shadow: 0 16px 34px -12px oklch(0 0 0 / .6);
    translate: 0 calc(100% + 16px); opacity: 0; visibility: hidden;
    transition: translate .5s var(--mgr-bulk-spring), opacity .25s, visibility 0s linear .5s;
    &.is-on { translate: 0 0; opacity: 1; visibility: visible; transition: translate .5s var(--mgr-bulk-spring), opacity .25s, visibility 0s; }
    &.is-error { background: var(--mgr-bulk-danger); color: oklch(0.16 0.03 27); }
    & span { flex: 1; min-width: 0; text-wrap: pretty; }
    & button { flex: none; border: 0; background: none; padding: 3px 6px; border-radius: 6px; font-weight: 750; color: oklch(0.45 0.13 70); }
    & button:hover { background: color-mix(in oklch, var(--mgr-bulk-bg) 10%, transparent); }
    &:not(.has-undo) button { display: none; }
  }
  & .mgr-bulk-timer { position: absolute; left: 0; right: 0; bottom: 0; height: 2px; background: var(--mgr-bulk-accent); transform-origin: left; transform: scaleX(0); }
  & .mgr-bulk-toast.is-on.has-undo .mgr-bulk-timer { animation: mgr-bulk-timer 6s linear forwards; }
  & .mgr-bulk-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

  @container (width < 340px) {
    & .mgr-bulk-hrow, & .mgr-bulk-row { grid-template-columns: 30px minmax(0, 1fr) 58px; }
    & .mgr-bulk-seats { display: none; }
    & .mgr-bulk-bar { left: 31px; }
    & .mgr-bulk-keys { display: none; }
  }
  @container (width >= 420px) {
    & .mgr-bulk-bar button span { display: inline; }
  }
}
@keyframes mgr-bulk-deny { 20%, 60% { translate: -3px 0; } 40%, 80% { translate: 3px 0; } }
@keyframes mgr-bulk-spin { to { rotate: 1turn; } }
@keyframes mgr-bulk-pop { from { scale: .4; opacity: 0; } }
@keyframes mgr-bulk-rise { from { opacity: 0; translate: 0 8px; } }
@keyframes mgr-bulk-timer { from { transform: scaleX(1); } to { transform: scaleX(0); } }
@media (prefers-reduced-motion: reduce) {
  .mgr-bulk {
    & .mgr-bulk-row::before, & .mgr-bulk-row::after { transition: none; }
    & .mgr-bulk-bar { transition: opacity .2s linear; }
    & .mgr-bulk-toast, & .mgr-bulk-toast.is-on { transition: opacity .2s linear, visibility 0s; translate: 0 0; }
    & .mgr-bulk-num { transition: none; }
    & .mgr-bulk-row.is-denied, & .mgr-bulk-bar [data-act="copy"].is-failed { animation: none; }
    & .mgr-bulk-row.is-pending .mgr-bulk-st::before { animation-duration: 2s; }
    & .mgr-bulk-confirm { transition: opacity .2s linear; }
  }
}

