const RM = matchMedia('(prefers-reduced-motion: reduce)');
const $ = s => root.querySelector(s), $$ = s => [...root.querySelectorAll(s)];
const body = $('.mgr-bulk-body'), bar = $('.mgr-bulk-bar'), all = $('[data-all]');
const num = $('.mgr-bulk-num'), sumEl = $('[data-sum]'), kpi = $('[data-kpi]'), countEl = $('[data-count]'), sr = $('[data-sr]');
const confirmEl = $('.mgr-bulk-confirm'), toast = $('.mgr-bulk-toast'), tmsg = $('[data-tmsg]');
const pauseBtn = $('[data-act="pause"]'), copyBtn = $('[data-act="copy"]'), cancelBtn = $('[data-act="cancel"]');
const emptyEl = $('.mgr-bulk-empty');
const fmt = v => '$' + Math.round(v).toLocaleString('en-US');
const ALL = $$('.mgr-bulk-row');
const live = () => ALL.filter(r => !r._gone);
const sel = new Set(ALL.filter(r => r.getAttribute('aria-selected') === 'true'));
let anchor = null, focusIdx = 0;
const selectable = r => r.dataset.status !== 'hold';
const say = m => { sr.textContent = ''; sr.textContent = m; };

/* number tweens for the KPI and the selection sum (the count itself is an @property counter) */
function tween(el, to, key) {
  const from = el[key] == null ? to : el[key], t0 = performance.now(), dur = RM.matches ? 0 : 520;
  cancelAnimationFrame(el._raf);
  const step = now => {
    if (!root.isConnected) return;
    const k = dur ? Math.min(1, (now - t0) / dur) : 1;
    el[key] = from + (to - from) * (1 - Math.pow(1 - k, 3));
    el.textContent = fmt(el[key]);
    if (k < 1) el._raf = requestAnimationFrame(step);
  };
  el._raf = requestAnimationFrame(step);
}

function sync() {
  const rows = live();
  rows.forEach(r => {
    const on = sel.has(r);
    r.setAttribute('aria-selected', on);
    r.querySelector('input').checked = on;
  });
  const pool = rows.filter(selectable), n = sel.size;
  all.checked = n > 0 && pool.every(r => sel.has(r));
  all.indeterminate = n > 0 && !all.checked;
  all.disabled = pool.length === 0;
  bar.classList.toggle('is-open', n > 0);
  bar.inert = n === 0;
  num.style.setProperty('--mgr-bulk-n', n);
  tween(sumEl, [...sel].reduce((a, r) => a + +r.dataset.mrr, 0), '_v');
  const anyActive = [...sel].some(r => r.dataset.status === 'active');
  pauseBtn.classList.toggle('is-resume', n > 0 && !anyActive);
  pauseBtn.title = n > 0 && !anyActive ? 'Resume' : 'Pause';
  pauseBtn.querySelector('span').textContent = pauseBtn.title;
  tween(kpi, rows.filter(r => r.dataset.status !== 'paused').reduce((a, r) => a + +r.dataset.mrr, 0), '_v');
  countEl.textContent = rows.length + (rows.length === 1 ? ' account' : ' accounts');
  root.classList.toggle('is-empty', rows.length === 0);
  emptyEl.hidden = rows.length > 0;
}
sumEl._v = [...sel].reduce((a, r) => a + +r.dataset.mrr, 0);
kpi._v = ALL.filter(r => r.dataset.status !== 'paused').reduce((a, r) => a + +r.dataset.mrr, 0);

function deny(r) {
  r.classList.remove('is-denied'); r.offsetWidth; r.classList.add('is-denied');
  say(r.querySelector('b').textContent + ' is on billing hold and cannot be changed');
}
function setSel(r, on) { if (!selectable(r)) return; on ? sel.add(r) : sel.delete(r); }
function range(a, b) {
  const rows = live(); const [lo, hi] = a < b ? [a, b] : [b, a];
  for (let i = lo; i <= hi; i++) setSel(rows[i], true);
}
function focusRow(i, move = true) {
  const rows = live(); if (!rows.length) return;
  focusIdx = Math.max(0, Math.min(rows.length - 1, i));
  rows.forEach((r, j) => { r.tabIndex = j === focusIdx ? 0 : -1; });
  if (move) rows[focusIdx].focus();
}
