const RM = matchMedia('(prefers-reduced-motion: reduce)');
const $ = s => root.querySelector(s), $$ = s => [...root.querySelectorAll(s)];
const grid = $('.mgr-sheet-grid'), cursor = $('.mgr-sheet-cursor'), ed = $('.mgr-sheet-editor');
const msg = $('[data-msg]'), stateEl = $('[data-state]'), saveBtn = $('[data-save]'), revertBtn = $('[data-revert]');
const totalEl = $('[data-total]'), leftEl = $('[data-left]'), meter = $('.mgr-sheet-meter');
const CAP = 60000, ROWS = 6, COLS = 4;
const nf = new Intl.NumberFormat('en-US');
const cells = [];
$$('.mgr-sheet-cell').forEach(c => { const r = +c.dataset.r, k = +c.dataset.c; (cells[r] = cells[r] || [])[k] = c; });
const orig = [], val = [];
for (let r = 0; r < 5; r++) { orig[r] = []; val[r] = []; for (let c = 0; c < 3; c++) { orig[r][c] = val[r][c] = +cells[r][c].textContent.replace(/\D/g, ''); } }
const defaultMsg = msg.innerHTML;
let ar = 0, ac = 0, editing = false, grand = 0, saving = false;
const editable = (r, c) => r < 5 && c < 3 && !cells[r][c].classList.contains('is-locked');

function say(text, kind) {
  msg.classList.toggle('is-error', kind === 'error'); msg.classList.toggle('is-warn', kind === 'warn');
  if (text == null) msg.innerHTML = defaultMsg; else msg.textContent = text;
}
function place(el) {
  const c = cells[ar][ac];
  el.style.setProperty('--x', c.offsetLeft + 'px'); el.style.setProperty('--y', c.offsetTop + 'px');
  el.style.setProperty('--w', c.offsetWidth + 'px'); el.style.setProperty('--h', c.offsetHeight + 'px');
}
function activate(r, c, focus = true) {
  ar = Math.max(0, Math.min(ROWS - 1, r)); ac = Math.max(0, Math.min(COLS - 1, c));
  cells.flat().forEach(x => { x.tabIndex = -1; x.classList.remove('is-active'); });
  const cell = cells[ar][ac];
  cell.tabIndex = 0; cell.classList.add('is-active');
  place(cursor);
  if (focus) cell.focus({ preventScroll: true });
}

/* parse 4200, $4,200, 4.2k; whole dollars only */
function parse(s) {
  const t = s.trim().toLowerCase().replace(/[$,\s]/g, '');
  const m = t.match(/^(\d+(?:\.\d+)?)(k?)$/);
  if (!m) return null;
  const v = parseFloat(m[1]) * (m[2] ? 1000 : 1);
  if (!Number.isFinite(v) || v > 99999 || Math.abs(v - Math.round(v)) > 1e-9) return null;
  return Math.round(v);
}

function tween(el, from, to, pre, post) {
  if (from === to) return;
  const t0 = performance.now(), dur = RM.matches ? 0 : 480;
  cancelAnimationFrame(el._raf);
  const step = now => {
    if (!root.isConnected) return;
    const k = dur ? Math.min(1, (now - t0) / dur) : 1;
    el.textContent = pre + nf.format(Math.round(from + (to - from) * (1 - Math.pow(1 - k, 3)))) + post;
    if (k < 1) el._raf = requestAnimationFrame(step);
  };
  el._raf = requestAnimationFrame(step);
}
function bump(el) { el.classList.remove('is-bump'); el.offsetWidth; el.classList.add('is-bump'); }

function recalc(changedR, changedC) {
  let g = 0;
  for (let r = 0; r < 5; r++) {
    const t = val[r].reduce((a, b) => a + b, 0); g += t;
    const el = cells[r][3], was = +el.textContent.replace(/\D/g, '');
    if (was !== t) { tween(el, was, t, '', ''); bump(el); }
  }
  for (let c = 0; c < 3; c++) {
    let t = 0; for (let r = 0; r < 5; r++) t += val[r][c];
    const el = cells[5][c], was = +el.textContent.replace(/\D/g, '');
    if (was !== t) { tween(el, was, t, '', ''); bump(el); }
  }
  const ge = cells[5][3], gw = +ge.textContent.replace(/\D/g, '');
  if (gw !== g) { tween(ge, gw, g, '', ''); bump(ge); }
  tween(totalEl, grand, g, '$', '');
  grand = g;
  const over = g > CAP;
  root.classList.toggle('is-over', over);
  root.style.setProperty('--mgr-sheet-pct', (g / CAP * 100).toFixed(2));
  meter.setAttribute('aria-valuenow', g);
  leftEl.textContent = over ? '$' + nf.format(g - CAP) + ' over cap' : '$' + nf.format(CAP - g) + ' left';
  const dirty = [];
  for (let r = 0; r < 5; r++) for (let c = 0; c < 3; c++) {
    const d = val[r][c] !== orig[r][c];
    cells[r][c].classList.toggle('is-dirty', d);
    if (d) dirty.push(1);
  }
  root.classList.remove('is-saved');
  stateEl.classList.toggle('is-dirty', dirty.length > 0);
  if (dirty.length) stateEl.textContent = dirty.length + (dirty.length === 1 ? ' unsaved change' : ' unsaved changes');
  revertBtn.disabled = !dirty.length || saving;
  saveBtn.disabled = !dirty.length || over || saving;
  saveBtn.title = over ? 'Bring the total under the cap to save' : '';
  return { over, dirty: dirty.length };
}

function startEdit(seed) {
  if (!editable(ar, ac)) {
    const c = cells[ar][ac];
    if (c.classList.contains('is-locked')) { c.classList.remove('is-denied'); c.offsetWidth; c.classList.add('is-denied'); say('Print in December is a signed contract, so the cell is locked.', 'error'); }
    else say('Totals are calculated from the cells, so they cannot be typed over.', 'warn');
    return;
  }
  editing = true;
  place(ed);
  ed.hidden = false;
  ed.removeAttribute('aria-invalid');
  ed.setAttribute('aria-label', 'Edit ' + $$('.mgr-sheet-rh')[ar].textContent + ', ' + ['October', 'November', 'December'][ac]);
  ed.value = seed != null ? seed : String(val[ar][ac]);
  ed.focus();
  if (seed == null) ed.select(); else ed.setSelectionRange(ed.value.length, ed.value.length);
  say('Enter a whole amount, like 4200 or 4.2k.');
}
function stopEdit(focus = true) { editing = false; ed.hidden = true; activate(ar, ac, focus); }
function commit(dr, dc, focus = true) {
  const v = parse(ed.value);
  if (v == null) {
    ed.setAttribute('aria-invalid', 'false'); ed.offsetWidth; ed.setAttribute('aria-invalid', 'true');
    say('“' + ed.value.trim() + '” is not an amount. Use whole dollars, like 4200 or 4.2k.', 'error');
    return false;
  }
  const was = val[ar][ac];
  val[ar][ac] = v;
  cells[ar][ac].textContent = nf.format(v);
  stopEdit(focus);
  const res = recalc();
  if (res.over) say('Over the $' + nf.format(CAP) + ' cap by $' + nf.format(grand - CAP) + '. Trim a cell to save.', 'warn');
  else say(was === v ? null : $$('.mgr-sheet-rh')[ar].textContent + ' ' + ['Oct', 'Nov', 'Dec'][ac] + ': ' + nf.format(was) + ' → ' + nf.format(v) + '.');
  activate(ar + dr, ac + dc, focus);
  return true;
}

grid.addEventListener('keydown', e => {
  if (e.target === ed) {
    if (e.key === 'Enter') { e.preventDefault(); commit(1, 0); }
    else if (e.key === 'Tab') { e.preventDefault(); commit(0, e.shiftKey ? -1 : 1); }
    else if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); stopEdit(); say(null); }
    return;
  }
  const mv = { ArrowUp: [-1, 0], ArrowDown: [1, 0], ArrowLeft: [0, -1], ArrowRight: [0, 1] }[e.key];
  if (mv) { e.preventDefault(); activate(ar + mv[0], ac + mv[1]); return; }
  if (e.key === 'Home') { e.preventDefault(); activate(e.ctrlKey || e.metaKey ? 0 : ar, 0); return; }
  if (e.key === 'End') { e.preventDefault(); activate(e.ctrlKey || e.metaKey ? ROWS - 1 : ar, COLS - 1); return; }
  if (e.key === 'Enter' || e.key === 'F2') { e.preventDefault(); startEdit(); return; }
  if ((e.key === 'Delete' || e.key === 'Backspace') && editable(ar, ac)) {
    e.preventDefault(); const was = val[ar][ac]; val[ar][ac] = 0; cells[ar][ac].textContent = '0'; recalc();
    say('Cleared ' + nf.format(was) + '. Revert brings it back.'); return;
  }
  if (e.key.length === 1 && /[\d.$]/.test(e.key) && !e.metaKey && !e.ctrlKey) { e.preventDefault(); startEdit(e.key); }
});
ed.addEventListener('input', () => ed.removeAttribute('aria-invalid'));
/* leaving the editor commits a valid value and discards an invalid one, without pulling focus back */
ed.addEventListener('blur', () => { if (editing && !commit(0, 0, false)) { stopEdit(false); say('That edit was discarded because it was not a valid amount.', 'error'); } });
grid.addEventListener('pointerdown', e => {
  const c = e.target.closest('.mgr-sheet-cell'); if (!c) return;
  if (editing && e.target !== ed) { if (!commit(0, 0)) { e.preventDefault(); return; } }
  activate(+c.dataset.r, +c.dataset.c);
  e.preventDefault();
});
grid.addEventListener('dblclick', e => { if (e.target.closest('.mgr-sheet-cell')) startEdit(); });

revertBtn.addEventListener('click', () => {
  for (let r = 0; r < 5; r++) for (let c = 0; c < 3; c++) { val[r][c] = orig[r][c]; cells[r][c].textContent = nf.format(orig[r][c]); }
  recalc(); stateEl.textContent = 'Changes reverted'; say(null); activate(ar, ac);
});
saveBtn.addEventListener('click', () => {
  saving = true; saveBtn.disabled = true; revertBtn.disabled = true;
  saveBtn.classList.add('is-busy'); $('[data-savel]').textContent = 'Saving';
  stateEl.classList.remove('is-dirty'); stateEl.textContent = 'Saving changes…';
  setTimeout(() => {
    if (!root.isConnected) return;
    for (let r = 0; r < 5; r++) for (let c = 0; c < 3; c++) orig[r][c] = val[r][c];
    saving = false; saveBtn.classList.remove('is-busy'); $('[data-savel]').textContent = 'Save';
    root.classList.add('is-saved');
    const t = new Date();
    stateEl.textContent = 'Saved at ' + String(t.getHours()).padStart(2, '0') + ':' + String(t.getMinutes()).padStart(2, '0');
    setTimeout(() => {
      if (!root.isConnected) return;
      $$('.mgr-sheet-cell.is-dirty').forEach(c => c.classList.remove('is-dirty'));
      root.classList.remove('is-saved');
    }, 520);
    say('Budget saved. ' + '$' + nf.format(CAP - grand) + ' of headroom remains.');
  }, RM.matches ? 400 : 900);
});

const ro = new ResizeObserver(() => { if (!root.isConnected) return ro.disconnect(); place(cursor); if (editing) place(ed); });
ro.observe(grid);
grand = val.flat().reduce((a, b) => a + b, 0);
recalc();
stateEl.textContent = 'All changes saved';
activate(0, 0, false);

