.mgr-rollup {
  --mgr-rollup-bg: oklch(0.2 0.028 22);
  --mgr-rollup-ink: oklch(0.94 0.02 60);
  --mgr-rollup-accent: oklch(0.8 0.12 52);
  --mgr-rollup-up: oklch(0.76 0.14 36);
  --mgr-rollup-down: oklch(0.8 0.09 150);
  --mgr-rollup-line: color-mix(in oklch, var(--mgr-rollup-ink) 9%, transparent);
  --mgr-rollup-dim: color-mix(in oklch, var(--mgr-rollup-ink) 52%, var(--mgr-rollup-bg));
  --mgr-rollup-raise: color-mix(in oklch, var(--mgr-rollup-ink) 5%, var(--mgr-rollup-bg));
  --mgr-rollup-ease: cubic-bezier(.2, .8, .2, 1);
  --mgr-rollup-spring: linear(0, 0.2 2.5%, 0.69 6.4%, 1.02 11.6%, 1.09 17.4%, 1.03 25.6%, 0.99 38%, 1);
  container-type: inline-size; position: relative;
  box-sizing: border-box; width: 100%; max-width: 470px; margin-inline: auto;
  padding: 15px 12px 10px; border-radius: 16px;
  background:
    radial-gradient(90% 50% at 0% 0%, color-mix(in oklch, var(--mgr-rollup-accent) 9%, transparent), transparent 70%),
    var(--mgr-rollup-bg);
  color: var(--mgr-rollup-ink); border: 1px solid var(--mgr-rollup-line);
  font: 400 12.5px/1.3 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--mgr-rollup-accent); outline-offset: 1px; border-radius: 6px; }

  & .mgr-rollup-head { display: flex; justify-content: space-between; align-items: flex-end; gap: 10px; margin-bottom: 10px; }
  & .mgr-rollup-head > div:first-child { min-width: 0; }
  & .mgr-rollup-head > :last-child { flex: none; }
  & .mgr-rollup-eyebrow { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin: 0 0 3px; font-size: 10px; font-weight: 600; letter-spacing: .1em; text-transform: uppercase; color: var(--mgr-rollup-dim); }
  & h3 { margin: 0; font-size: clamp(17px, 5.8cqi, 21px); font-weight: 670; letter-spacing: -.025em; line-height: 1.05; text-wrap: balance; }
  & .mgr-rollup-total {
    display: grid; justify-items: end; gap: 2px;
    & b { font-size: clamp(16px, 5.4cqi, 20px); font-weight: 680; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
    & small { font-size: 10.5px; color: var(--mgr-rollup-up); font-variant-numeric: tabular-nums; font-weight: 600; }
  }

  /* composition bar: one segment per group, keyed, widths eased on regroup */
  & .mgr-rollup-stack { display: flex; gap: 2px; height: 8px; margin-bottom: 10px; border-radius: 4px; overflow: hidden; }
  & .mgr-rollup-sg {
    flex: 0 0 calc(var(--s) * (100% - var(--gaps, 6px))); min-width: 2px; border-radius: 2px; background: var(--c);
    transition: flex-basis .7s var(--mgr-rollup-ease), opacity .25s, filter .25s;
    @starting-style { flex-basis: 0%; }
    cursor: pointer;
  }
  & .mgr-rollup-stack:hover .mgr-rollup-sg:not(:hover) { opacity: .45; }

  & .mgr-rollup-tools { display: flex; justify-content: space-between; align-items: center; gap: 8px; margin-bottom: 8px; }
  & .mgr-rollup-seg {
    display: inline-flex; padding: 2px; border-radius: 9px; background: var(--mgr-rollup-raise); border: 1px solid var(--mgr-rollup-line);
    & button {
      border: 0; background: none; padding: 4px 9px; border-radius: 7px; font-size: 11.5px; font-weight: 600; color: var(--mgr-rollup-dim);
      transition: background .25s, color .25s;
      &[aria-checked="true"] { background: color-mix(in oklch, var(--mgr-rollup-ink) 12%, transparent); color: var(--mgr-rollup-ink); }
      &:hover { color: var(--mgr-rollup-ink); }
    }
  }
  & .mgr-rollup-all {
    display: inline-flex; align-items: center; gap: 4px; border: 0; background: none; padding: 4px 6px; border-radius: 7px;
    font-size: 11.5px; font-weight: 600; color: var(--mgr-rollup-dim);
    &:hover { color: var(--mgr-rollup-ink); background: var(--mgr-rollup-raise); }
    & svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; transition: rotate .45s var(--mgr-rollup-spring); }
    &[aria-pressed="true"] svg { rotate: 180deg; }
  }

  & .mgr-rollup-tree {
    max-height: 292px; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin;
    scrollbar-color: var(--mgr-rollup-line) transparent;
    border-top: 1px solid var(--mgr-rollup-line);
  }
  & .mgr-rollup-grow, & .mgr-rollup-item {
    display: grid; grid-template-columns: minmax(0, 1fr) clamp(56px, 22cqi, 110px) 74px; align-items: center; gap: 10px;
    padding: 0 6px; outline: none; border-radius: 7px;
  }
  & .mgr-rollup-grow {
    height: 40px; cursor: pointer; position: relative;
    border-bottom: 1px solid var(--mgr-rollup-line); border-radius: 0;
    &:hover { background: var(--mgr-rollup-raise); }
    &:focus-visible { box-shadow: inset 0 0 0 1.5px var(--mgr-rollup-accent); outline: none; }
  }
  & .mgr-rollup-group.is-hl .mgr-rollup-grow { background: color-mix(in oklch, var(--c) 12%, transparent); }
  & .mgr-rollup-gname {
    display: flex; align-items: center; gap: 7px; min-width: 0;
    & svg { flex: none; width: 12px; height: 12px; fill: none; stroke: var(--mgr-rollup-dim); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; transition: rotate .45s var(--mgr-rollup-spring); }
    & .mgr-rollup-dot { flex: none; width: 8px; height: 8px; border-radius: 3px; background: var(--c); }
    & b { font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & i { font-style: normal; font-size: 10px; font-weight: 650; color: var(--mgr-rollup-dim); padding: 1px 5px; border-radius: 99px; background: var(--mgr-rollup-raise); font-variant-numeric: tabular-nums; }
  }
  & [aria-expanded="true"] .mgr-rollup-gname svg { rotate: 90deg; }
  & .mgr-rollup-share { display: flex; align-items: center; gap: 6px; min-width: 0; & .mgr-rollup-bar { flex: 1; min-width: 0; } }
  & .mgr-rollup-bar {
    height: 6px; border-radius: 3px; background: color-mix(in oklch, var(--mgr-rollup-ink) 7%, transparent); overflow: hidden;
    & i { display: block; height: 100%; border-radius: 3px; background: var(--c, var(--mgr-rollup-accent)); transform-origin: left; transform: scaleX(var(--s)); transition: transform .7s var(--mgr-rollup-ease); }
  }
  & .mgr-rollup-item .mgr-rollup-bar { height: 4px; & i { background: color-mix(in oklch, var(--c) 60%, transparent); } }
  & .mgr-rollup-num {
    display: grid; justify-items: end; gap: 1px; font-variant-numeric: tabular-nums; white-space: nowrap;
    & b { font-weight: 650; }
    & small { font-size: 10px; font-weight: 600; }
    & small.up { color: var(--mgr-rollup-up); }
    & small.down { color: var(--mgr-rollup-down); }
  }
  & .mgr-rollup-item .mgr-rollup-num b { font-weight: 500; }
  & .mgr-rollup-pct { flex: none; width: 3ch; text-align: right; font-size: 10px; font-weight: 600; color: var(--mgr-rollup-dim); font-variant-numeric: tabular-nums; }

  /* disclosure: 0fr to 1fr rows, children stagger in with --i */
  & .mgr-rollup-kids { display: grid; grid-template-rows: 0fr; transition: grid-template-rows .45s var(--mgr-rollup-ease); }
  & .mgr-rollup-kids-in { min-height: 0; overflow: hidden; }
  & [aria-expanded="true"] + .mgr-rollup-kids { grid-template-rows: 1fr; }
  & .mgr-rollup-item {
    height: 34px; margin-left: 18px; position: relative; opacity: .0; translate: -6px 0;
    transition: opacity .3s, translate .45s var(--mgr-rollup-ease), background .2s;
    &::before { content: ""; position: absolute; left: -9px; top: 0; bottom: 0; width: 1px; background: var(--mgr-rollup-line); }
    &:hover { background: var(--mgr-rollup-raise); }
    &:focus-visible { box-shadow: inset 0 0 0 1.5px var(--mgr-rollup-accent); }
  }
  & [aria-expanded="true"] + .mgr-rollup-kids .mgr-rollup-item { opacity: 1; translate: 0 0; transition-delay: calc(var(--i, 0) * 40ms + 60ms); }
  & .mgr-rollup-iname {
    display: grid; min-width: 0;
    & b { font: 500 12px/1.2 ui-monospace, "SF Mono", Menlo, monospace; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & small { font-size: 10px; color: var(--mgr-rollup-dim); }
  }
  & .mgr-rollup-kids-in > :last-child { margin-bottom: 4px; }
  & .is-fly { position: relative; z-index: 1; background: var(--mgr-rollup-bg); box-shadow: 0 10px 20px -12px oklch(0 0 0 / .8); }
  &.is-instant .mgr-rollup-kids, &.is-instant .mgr-rollup-item { transition: none; }

  & .mgr-rollup-foot {
    display: flex; justify-content: space-between; gap: 8px; margin-top: 8px; font-size: 10.5px; color: var(--mgr-rollup-dim);
    & i { display: inline-block; width: 6px; height: 6px; border-radius: 50%; margin: 0 3px 0 6px; }
    & .up { background: var(--mgr-rollup-up); }
    & .down { background: var(--mgr-rollup-down); }
  }
  & .mgr-rollup-legend { white-space: nowrap; }

  @container (width < 330px) {
    & .mgr-rollup-grow, & .mgr-rollup-item { grid-template-columns: minmax(0, 1fr) 64px; }
    & .mgr-rollup-share { display: none; }
    & .mgr-rollup-legend { display: none; }
  }
}
@media (prefers-reduced-motion: reduce) {
  .mgr-rollup {
    & .mgr-rollup-kids, & .mgr-rollup-sg, & .mgr-rollup-bar i, & .mgr-rollup-gname svg, & .mgr-rollup-all svg { transition: none; }
    & .mgr-rollup-item, & [aria-expanded="true"] + .mgr-rollup-kids .mgr-rollup-item { translate: 0 0; transition: opacity .2s linear; transition-delay: 0s; }
  }
}

