const tree = $('.mgr-rollup-tree'), stack = $('.mgr-rollup-stack'), allBtn = $('[data-all]'), foot = $('[data-foot]');
const segBtns = [...root.querySelectorAll('.mgr-rollup-seg [role="radio"]')];
const COLORS = ['oklch(0.8 0.12 52)', 'oklch(0.84 0.07 92)', 'oklch(0.72 0.13 12)', 'oklch(0.79 0.07 160)'];
const ENV = { prod: 'Production', staging: 'Staging', dev: 'Development' };
const TOTAL = DATA.reduce((a, d) => a + d.cost, 0);
const money = v => '$' + v.toLocaleString('en-US');
const pct = (c, p) => { const d = (c - p) / p * 100; return { t: (d >= 0 ? '+' : '−') + Math.abs(d).toFixed(1) + '%', cls: d >= 0 ? 'up' : 'down' }; };
const chev = '<svg viewBox="0 0 12 12" aria-hidden="true"><path d="m4.5 2.5 3.5 3.5-3.5 3.5"/></svg>';
let by = 'team';
const expanded = { team: new Set(), env: new Set() };
let focusKey = null;

/* item rows are created once and only ever moved, so FLIP can follow them between groups */
const items = new Map(DATA.map(d => {
  const el = document.createElement('div');
  el.className = 'mgr-rollup-item'; el.setAttribute('role', 'row'); el.setAttribute('aria-level', '2'); el.tabIndex = -1;
  el.dataset.key = 'i:' + d.id;
  const ch = pct(d.cost, d.prev);
  el.innerHTML = '<span role="gridcell" class="mgr-rollup-iname"><b></b><small></small></span>' +
    '<span role="gridcell" class="mgr-rollup-share"><span class="mgr-rollup-bar"><i></i></span></span>' +
    '<span role="gridcell" class="mgr-rollup-num"><b>' + money(d.cost) + '</b><small class="' + ch.cls + '">' + ch.t + '</small></span>';
  el.querySelector('b').textContent = d.id;
  return [d.id, el];
}));
const groups = new Map();
function groupEl(key) {
  if (groups.has(key)) return groups.get(key);
  const g = document.createElement('div');
  g.className = 'mgr-rollup-group'; g.dataset.g = key;
  g.innerHTML = '<div class="mgr-rollup-grow" role="row" aria-level="1" tabindex="-1">' +
    '<span role="gridcell" class="mgr-rollup-gname">' + chev + '<span class="mgr-rollup-dot"></span><b></b><i></i></span>' +
    '<span role="gridcell" class="mgr-rollup-share"><span class="mgr-rollup-bar"><i></i></span><span class="mgr-rollup-pct"></span></span>' +
    '<span role="gridcell" class="mgr-rollup-num"><b></b><small></small></span></div>' +
    '<div class="mgr-rollup-kids" role="rowgroup"><div class="mgr-rollup-kids-in"></div></div>';
  g.querySelector('.mgr-rollup-grow').dataset.key = 'g:' + key;
  groups.set(key, g);
  return g;
}

function model() {
  const m = new Map();
  DATA.forEach(d => { const k = d[by]; if (!m.has(k)) m.set(k, []); m.get(k).push(d); });
  return [...m.entries()].map(([k, list]) => ({
    key: k, label: by === 'env' ? ENV[k] : k, list: list.sort((a, b) => b.cost - a.cost),
    cost: list.reduce((a, d) => a + d.cost, 0), prev: list.reduce((a, d) => a + d.prev, 0)
  })).sort((a, b) => b.cost - a.cost);
}

function render(animate) {
  const gs = model();
  if (!expanded[by].size && !render.seeded) { expanded[by].add(gs[0].key); }
  /* FIRST: where every visible row is now */
  const first = new Map();
  if (animate) tree.querySelectorAll('[data-key]').forEach(el => { if (el.offsetParent && el.getClientRects().length) first.set(el.dataset.key, el.getBoundingClientRect()); });
  root.classList.add('is-instant');
  const keep = new Set();
  gs.forEach((g, gi) => {
    const el = groupEl(g.key); keep.add(el);
    el.style.setProperty('--c', COLORS[gi % COLORS.length]);
    const row = el.firstElementChild, open = expanded[by].has(g.key);
    row.setAttribute('aria-expanded', open);
    row.querySelector('b').textContent = g.label;
    row.querySelector('.mgr-rollup-gname i').textContent = g.list.length;
    row.querySelector('.mgr-rollup-bar i').style.setProperty('--s', (g.cost / TOTAL).toFixed(4));
    row.querySelector('.mgr-rollup-pct').textContent = (g.cost / TOTAL * 100).toFixed(0) + '%';
    row.querySelector('.mgr-rollup-share').title = (g.cost / TOTAL * 100).toFixed(1) + '% of September spend';
    row.querySelector('.mgr-rollup-num b').textContent = money(g.cost);
    const ch = pct(g.cost, g.prev), sm = row.querySelector('.mgr-rollup-num small');
    sm.textContent = ch.t; sm.className = ch.cls;
    row.setAttribute('aria-label', g.label + ', ' + g.list.length + ' services, ' + money(g.cost) + ', ' + ch.t + ' versus August');
    const kids = el.querySelector('.mgr-rollup-kids'), inner = kids.firstElementChild;
    kids.inert = !open;
    g.list.forEach((d, i) => {
      const it = items.get(d.id);
      it.style.setProperty('--i', i);
      it.querySelector('small').textContent = by === 'team' ? ENV[d.env] : d.team;
      it.querySelector('.mgr-rollup-bar i').style.setProperty('--s', (d.cost / g.cost).toFixed(4));
      inner.appendChild(it);
    });
    tree.appendChild(el);
  });
  groups.forEach(el => { if (!keep.has(el)) el.remove(); });
  tree.setAttribute('aria-label', 'Spend grouped by ' + (by === 'env' ? 'environment' : 'team'));

  /* composition bar */
  stack.style.setProperty('--gaps', (gs.length - 1) * 2 + 'px');
  const segs = new Map([...stack.children].map(s => [s.dataset.g, s]));
  stack.textContent = '';
  gs.forEach((g, gi) => {
    const s = segs.get(by + ':' + g.key) || Object.assign(document.createElement('span'), { className: 'mgr-rollup-sg' });
    s.dataset.g = by + ':' + g.key; s.dataset.key = g.key;
    s.style.setProperty('--s', (g.cost / TOTAL).toFixed(4));
    s.style.setProperty('--c', COLORS[gi % COLORS.length]);
    s.title = g.label + ' ' + (g.cost / TOTAL * 100).toFixed(1) + '%';
    stack.appendChild(s);
  });
  foot.textContent = DATA.length + ' services · ' + gs.length + (by === 'env' ? ' environments' : ' teams');
  syncAll(gs);
  rove();
  tree.offsetHeight;
  root.classList.remove('is-instant');
  /* LAST + INVERT + PLAY */
  if (animate && !RM.matches) {
    let n = 0;
    tree.querySelectorAll('[data-key]').forEach(el => {
      if (!el.getClientRects().length) return;
      const r = el.getBoundingClientRect(), f = first.get(el.dataset.key);
      if (f && (Math.abs(f.top - r.top) > .5 || Math.abs(f.left - r.left) > .5)) {
        /* a flying row gets an opaque surface so crossing rows occlude instead of overprinting */
        el.classList.add('is-fly');
        el.animate([{ transform: 'translate(' + (f.left - r.left) + 'px,' + (f.top - r.top) + 'px)' }, { transform: 'none' }],
          { duration: 820, delay: n++ * 16, easing: SPRING, fill: 'backwards' }).finished.then(() => el.classList.remove('is-fly'), () => el.classList.remove('is-fly'));
      } else if (!f && el.closest('[aria-expanded="true"] + .mgr-rollup-kids, .mgr-rollup-group > .mgr-rollup-grow')) {
        el.animate([{ opacity: 0, transform: 'translateY(6px)' }, { opacity: 1, transform: 'none' }], { duration: 360, delay: 80, easing: 'cubic-bezier(.2,.8,.2,1)', fill: 'backwards' });
      }
    });
  }
  render.seeded = true;
}

function syncAll(gs) {
  gs = gs || model();
  const allOpen = gs.every(g => expanded[by].has(g.key));
  allBtn.setAttribute('aria-pressed', allOpen);
  allBtn.querySelector('span').textContent = allOpen ? 'Collapse all' : 'Expand all';
}

/* ---- disclosure ---- */
function setOpen(key, open) {
  open ? expanded[by].add(key) : expanded[by].delete(key);
  const g = groups.get(key); if (!g) return;
  g.firstElementChild.setAttribute('aria-expanded', open);
  g.querySelector('.mgr-rollup-kids').inert = !open;
  syncAll(); rove();
}
tree.addEventListener('click', e => {
  const row = e.target.closest('.mgr-rollup-grow, .mgr-rollup-item'); if (!row) return;
  focusKey = row.dataset.key;
  if (row.classList.contains('mgr-rollup-grow')) { const k = row.parentElement.dataset.g; setOpen(k, !expanded[by].has(k)); }
  rove(true);
});
allBtn.addEventListener('click', () => {
  const gs = model(), open = !gs.every(g => expanded[by].has(g.key));
  gs.forEach(g => setOpen(g.key, open));
});
stack.addEventListener('click', e => {
  const s = e.target.closest('.mgr-rollup-sg'); if (!s) return;
  setOpen(s.dataset.key, true);
  const g = groups.get(s.dataset.key);
  focusKey = 'g:' + s.dataset.key; rove(true);
  g.firstElementChild.scrollIntoView({ block: 'nearest', behavior: RM.matches ? 'auto' : 'smooth' });
});
stack.addEventListener('pointerover', e => { const s = e.target.closest('.mgr-rollup-sg'); groups.forEach((g, k) => g.classList.toggle('is-hl', !!s && s.dataset.key === k)); });
stack.addEventListener('pointerleave', () => groups.forEach(g => g.classList.remove('is-hl')));

/* ---- treegrid keyboard: one tab stop, arrows walk visible rows ---- */
const visibleRows = () => [...tree.querySelectorAll('.mgr-rollup-grow, [aria-expanded="true"] + .mgr-rollup-kids .mgr-rollup-item')];
function rove(focus) {
  const rows = visibleRows();
  let cur = rows.find(r => r.dataset.key === focusKey);
  if (!cur) { cur = rows[0]; focusKey = cur && cur.dataset.key; }
  rows.forEach(r => { r.tabIndex = r === cur ? 0 : -1; });
  tree.querySelectorAll('.mgr-rollup-item').forEach(r => { if (!rows.includes(r)) r.tabIndex = -1; });
  if (focus && cur) cur.focus({ preventScroll: false });
}
tree.addEventListener('keydown', e => {
  const rows = visibleRows(), i = rows.findIndex(r => r.dataset.key === focusKey);
  if (i < 0) return;
  const row = rows[i], isGroup = row.classList.contains('mgr-rollup-grow');
  const key = isGroup ? row.parentElement.dataset.g : null;
  let j = null;
  switch (e.key) {
    case 'ArrowDown': j = i + 1; break;
    case 'ArrowUp': j = i - 1; break;
    case 'Home': j = 0; break;
    case 'End': j = rows.length - 1; break;
    case 'ArrowRight':
      if (isGroup && !expanded[by].has(key)) setOpen(key, true);
      else if (isGroup) j = i + 1;
      break;
    case 'ArrowLeft':
      if (isGroup && expanded[by].has(key)) setOpen(key, false);
      else if (!isGroup) { focusKey = row.closest('.mgr-rollup-group').firstElementChild.dataset.key; rove(true); }
      break;
    case 'Enter': case ' ':
      if (isGroup) setOpen(key, !expanded[by].has(key));
      break;
    default: return;
  }
  e.preventDefault();
  if (j != null) { j = Math.max(0, Math.min(rows.length - 1, j)); focusKey = rows[j].dataset.key; rove(true); }
});

/* ---- group-by switch: rows FLIP from their old group into the new one ---- */
function pick(next, focus) {
  if (next === by) return;
  by = next;
  segBtns.forEach(b => { const on = b.dataset.by === by; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; if (on && focus) b.focus(); });
  if (!expanded[by].size) expanded[by].add(model()[0].key);
  render(true);
}
segBtns.forEach(b => b.addEventListener('click', () => pick(b.dataset.by)));
$('.mgr-rollup-seg').addEventListener('keydown', e => {
  if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) return;
  e.preventDefault(); pick(by === 'team' ? 'env' : 'team', true);
});

render(false);

css:
.mgr-cohort {
  --mgr-cohort-paper: oklch(0.975 0.012 80);
  --mgr-cohort-ink: oklch(0.27 0.035 350);
  --mgr-cohort-hot: oklch(0.43 0.16 352);
  --mgr-cohort-cool: oklch(0.955 0.022 25);
  --mgr-cohort-peak: 55;
  --mgr-cohort-line: color-mix(in oklch, var(--mgr-cohort-ink) 10%, transparent);
  --mgr-cohort-dim: color-mix(in oklch, var(--mgr-cohort-ink) 55%, var(--mgr-cohort-paper));
  --mgr-cohort-col: 46px;
  container-type: inline-size; position: relative;
  box-sizing: border-box; width: 100%; max-width: 520px; margin-inline: auto;
  padding: 15px 12px 10px; border-radius: 14px;
  background: var(--mgr-cohort-paper); color: var(--mgr-cohort-ink);
  border: 1px solid color-mix(in oklch, var(--mgr-cohort-ink) 9%, transparent);
  box-shadow: 0 22px 44px -28px oklch(0.3 0.08 350 / .5);
  font: 400 12px/1.3 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  timeline-scope: --mgr-cohort-x, --mgr-cohort-y;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--mgr-cohort-hot); outline-offset: 1px; }

  & .mgr-cohort-head { display: flex; justify-content: space-between; align-items: flex-end; gap: 10px; margin-bottom: 10px; }
  & .mgr-cohort-head > div:first-child { min-width: 0; }
  & .mgr-cohort-head > :last-child { flex: none; }
  & .mgr-cohort-eyebrow { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin: 0 0 3px; font-size: 10px; font-weight: 600; letter-spacing: .1em; text-transform: uppercase; color: var(--mgr-cohort-dim); }
  & h3 { margin: 0; font-size: clamp(17px, 5.8cqi, 21px); font-weight: 680; letter-spacing: -.025em; line-height: 1.05; text-wrap: balance; }
  & .mgr-cohort-kpi {
    display: flex; align-items: center; gap: 7px; text-align: right;
    & b { font-size: clamp(18px, 6.4cqi, 24px); font-weight: 700; letter-spacing: -.03em; color: var(--mgr-cohort-hot); font-variant-numeric: tabular-nums; }
    & small { font-size: 10px; line-height: 1.25; color: var(--mgr-cohort-dim); }
    & span { display: block; color: var(--mgr-cohort-ink); font-weight: 600; font-variant-numeric: tabular-nums; }
  }

  & .mgr-cohort-bar { display: flex; justify-content: space-between; align-items: center; gap: 8px; margin-bottom: 8px; }
  & .mgr-cohort-seg {
    display: inline-flex; padding: 2px; border-radius: 9px; border: 1px solid var(--mgr-cohort-line);
    background: color-mix(in oklch, var(--mgr-cohort-ink) 3%, var(--mgr-cohort-paper));
    & button {
      border: 0; background: none; padding: 4px 9px; border-radius: 7px; font-size: 11.5px; font-weight: 600; color: var(--mgr-cohort-dim);
      transition: background .25s, color .25s, box-shadow .25s;
      &[aria-checked="true"] { background: oklch(1 0 0); color: var(--mgr-cohort-ink); box-shadow: 0 1px 2px oklch(0.3 0.05 350 / .15), 0 0 0 1px var(--mgr-cohort-line); }
    }
  }
  & .mgr-cohort-scale {
    display: inline-flex; align-items: center; gap: 5px; font: 500 9.5px ui-monospace, Menlo, monospace; color: var(--mgr-cohort-dim);
    & i { width: 54px; height: 6px; border-radius: 3px; background: linear-gradient(90deg, var(--mgr-cohort-cool), var(--mgr-cohort-hot)); }
  }

  /* one scroller, three sticky edges; its own scroll timelines drive the edge shadows */
  & .mgr-cohort-scroll {
    position: relative; max-height: 258px; overflow: auto; overscroll-behavior: contain; border-radius: 9px;
    border: 1px solid var(--mgr-cohort-line); background: oklch(1 0 0);
    scroll-timeline: --mgr-cohort-x inline, --mgr-cohort-y block;
    scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--mgr-cohort-ink) 18%, transparent) transparent;
  }
  & .mgr-cohort-table { border-collapse: separate; border-spacing: 0; font-variant-numeric: tabular-nums; width: max-content; min-width: 100%; }
  & .mgr-cohort-table th, & .mgr-cohort-table td { padding: 0; height: 28px; }
  & .mgr-cohort-table thead th {
    position: sticky; top: 0; z-index: 2; min-width: var(--mgr-cohort-col); height: 26px;
    background: oklch(1 0 0); border-bottom: 1px solid var(--mgr-cohort-line);
    font: 650 9.5px/1 system-ui, sans-serif; letter-spacing: .08em; color: var(--mgr-cohort-dim); text-align: center;
    transition: color .2s, box-shadow .2s;
  }
  & .mgr-cohort-table th[scope="row"], & .mgr-cohort-corner {
    position: sticky; left: 0; z-index: 1; min-width: 92px; padding: 0 8px; text-align: left;
    background: oklch(1 0 0); border-right: 1px solid var(--mgr-cohort-line);
    & b { display: block; font-size: 11.5px; font-weight: 620; color: var(--mgr-cohort-ink); white-space: nowrap; letter-spacing: 0; text-transform: none; transition: color .2s; }
    & small { display: block; font: 500 9.5px/1.1 ui-monospace, Menlo, monospace; color: var(--mgr-cohort-dim); letter-spacing: 0; text-transform: none; }
    &::after {
      content: ""; position: absolute; top: 0; bottom: 0; left: 100%; width: 10px; pointer-events: none; opacity: 0;
      background: linear-gradient(90deg, oklch(0.3 0.06 350 / .16), transparent);
    }
  }
  & .mgr-cohort-table thead .mgr-cohort-corner { z-index: 3; text-align: left; letter-spacing: .08em; text-transform: uppercase; }
  & .mgr-cohort-table thead .mgr-cohort-corner small { display: inline; margin-left: 4px; font: 500 9px system-ui, sans-serif; letter-spacing: .02em; text-transform: none; }
  & .mgr-cohort-table thead th:not(.mgr-cohort-corner)::after {
    content: ""; position: absolute; left: 0; right: 0; top: 100%; height: 8px; pointer-events: none; opacity: 0;
    background: linear-gradient(oklch(0.3 0.06 350 / .14), transparent);
  }
  & .mgr-cohort-table tfoot :is(th, td) {
    position: sticky; bottom: 0; z-index: 1; height: 30px;
    border-top: 1px solid color-mix(in oklch, var(--mgr-cohort-ink) 22%, transparent);
    box-shadow: 0 -8px 12px -10px oklch(0.3 0.06 350 / .25);
  }
  & .mgr-cohort-table tfoot th[scope="row"] { z-index: 2; }
  & .mgr-cohort-table tfoot b { font-weight: 700; }

  /* heat: the colour is a mix weighted by --p; the ink flips past the midpoint with clamp() */
  & .mgr-cohort-v {
    --k: min(var(--p) / var(--mgr-cohort-peak), 1);
    --flip: clamp(0, (var(--k) - .55) * 100, 1);
    min-width: var(--mgr-cohort-col); text-align: center; cursor: default; outline-offset: -2px;
    font: 500 10.5px/1 ui-monospace, "SF Mono", Menlo, monospace;
    background: color-mix(in oklch, var(--mgr-cohort-hot) calc(var(--k) * 100%), var(--mgr-cohort-cool));
    color: color-mix(in oklch, oklch(0.99 0.01 80) calc(var(--flip) * 100%), var(--mgr-cohort-ink));
    box-shadow: inset -1px -1px 0 oklch(1 0 0 / .7);
    transition: opacity .2s;
    animation: mgr-cohort-in .55s cubic-bezier(.2, .8, .2, 1) both;
    animation-delay: calc(var(--d) * 28ms);
  }
  & .mgr-cohort-v.is-w0 { background: color-mix(in oklch, var(--mgr-cohort-ink) 5%, oklch(1 0 0)); color: var(--mgr-cohort-dim); }
  & .mgr-cohort-na {
    min-width: var(--mgr-cohort-col);
    background: repeating-linear-gradient(-45deg, transparent 0 4px, color-mix(in oklch, var(--mgr-cohort-ink) 6%, transparent) 4px 5px);
  }
  & .mgr-cohort-table.is-swap .mgr-cohort-v { animation: mgr-cohort-swap .4s cubic-bezier(.2, .8, .2, 1) both; animation-delay: calc(var(--d) * 14ms); }

  /* crosshair: :has() fades everything except the hovered row and column */
  & .mgr-cohort-table:has(.mgr-cohort-v:is(:hover, :focus-visible)) .mgr-cohort-v { opacity: .4; }
  & .mgr-cohort-table tr:has(.mgr-cohort-v:is(:hover, :focus-visible)) .mgr-cohort-v { opacity: 1; }
  & .mgr-cohort-table tr:has(.mgr-cohort-v:is(:hover, :focus-visible)) th b { color: var(--mgr-cohort-hot); }
  & .mgr-cohort-table:has(.mgr-cohort-v[data-c="0"]:is(:hover, :focus-visible)) :is(.mgr-cohort-v[data-c="0"], th[data-c="0"]) { opacity: 1; }
  & .mgr-cohort-table:has(.mgr-cohort-v[data-c="0"]:is(:hover, :focus-visible)) th[data-c="0"] { color: var(--mgr-cohort-hot); box-shadow: inset 0 -2px 0 var(--mgr-cohort-hot); }
  & .mgr-cohort-table:has(.mgr-cohort-v[data-c="1"]:is(:hover, :focus-visible)) :is(.mgr-cohort-v[data-c="1"], th[data-c="1"]) { opacity: 1; }
  & .mgr-cohort-table:has(.mgr-cohort-v[data-c="1"]:is(:hover, :focus-visible)) th[data-c="1"] { color: var(--mgr-cohort-hot); box-shadow: inset 0 -2px 0 var(--mgr-cohort-hot); }
  & .mgr-cohort-table:has(.mgr-cohort-v[data-c="2"]:is(:hover, :focus-visible)) :is(.mgr-cohort-v[data-c="2"], th[data-c="2"]) { opacity: 1; }
  & .mgr-cohort-table:has(.mgr-cohort-v[data-c="2"]:is(:hover, :focus-visible)) th[data-c="2"] { color: var(--mgr-cohort-hot); box-shadow: inset 0 -2px 0 var(--mgr-cohort-hot); }
  & .mgr-cohort-table:has(.mgr-cohort-v[data-c="3"]:is(:hover, :focus-visible)) :is(.mgr-cohort-v[data-c="3"], th[data-c="3"]) { opacity: 1; }
  & .mgr-cohort-table:has(.mgr-cohort-v[data-c="3"]:is(:hover, :focus-visible)) th[data-c="3"] { color: var(--mgr-cohort-hot); box-shadow: inset 0 -2px 0 var(--mgr-cohort-hot); }
  & .mgr-cohort-table:has(.mgr-cohort-v[data-c="4"]:is(:hover, :focus-visible)) :is(.mgr-cohort-v[data-c="4"], th[data-c="4"]) { opacity: 1; }
