const $ = s => root.querySelector(s), $$ = s => [...root.querySelectorAll(s)];
const table = $('.mgr-cohort-table'), scroller = $('.mgr-cohort-scroll'), read = $('[data-read]');
const segs = $$('.mgr-cohort-seg [role="radio"]');
const nf = new Intl.NumberFormat('en-US');
const cells = $$('.mgr-cohort-v');
const grid = [];
cells.forEach(c => { const r = +c.dataset.r, k = +c.dataset.c; (grid[r] = grid[r] || [])[k] = c; });
const rowKeys = Object.keys(grid).map(Number).sort((a, b) => a - b);
const label = r => r === 10 ? 'All cohorts (weighted)' : 'Cohort of ' + root.querySelector('th[data-r="' + r + '"] b').textContent;
let mode = 'pct', cur = grid[0][1];

function text(c) {
  const u = +c.dataset.u, s = +c.dataset.s;
  return mode === 'pct' ? Math.round(u / s * 100) + '%' : nf.format(u);
}
/* compare rates, not counts: the weighted row's denominator changes from week to week */
function delta(prev, rate) {
  const d = (+prev.dataset.u / +prev.dataset.s - rate) * 100;
  return (d >= 0 ? 'down ' : 'up ') + Math.abs(d).toFixed(1) + ' pts';
}
function describe(c) {
  const u = +c.dataset.u, s = +c.dataset.s, w = +c.dataset.c, r = +c.dataset.r;
  read.innerHTML = '<b>' + label(r) + '</b>, week ' + w + ': ' + nf.format(u) + ' of ' + nf.format(s) + ' users active, <em>' + (u / s * 100).toFixed(1) + '%</em>' +
    (w > 0 && grid[r][w - 1] ? ', ' + delta(grid[r][w - 1], u / s) + ' from week ' + (w - 1) + '.' : '.');
}
cells.forEach(c => c.setAttribute('aria-label', label(+c.dataset.r) + ', week ' + c.dataset.c + ', ' + (+c.dataset.u / +c.dataset.s * 100).toFixed(1) + ' percent, ' + nf.format(+c.dataset.u) + ' users'));

/* roving tabindex over the data cells; arrows skip the not-yet-reached triangle */
function focusCell(c, scroll) {
  if (!c) return;
  cells.forEach(x => { x.tabIndex = -1; });
  c.tabIndex = 0; cur = c;
  c.focus({ preventScroll: !scroll });
  if (scroll) c.scrollIntoView({ block: 'nearest', inline: 'nearest' });
  describe(c);
}
cur.tabIndex = 0;
table.addEventListener('keydown', e => {
  const c = e.target.closest('.mgr-cohort-v'); if (!c) return;
  let r = +c.dataset.r, k = +c.dataset.c, ri = rowKeys.indexOf(r);
  const row = grid[r];
  let next = null;
  if (e.key === 'ArrowRight') next = row[k + 1];
  else if (e.key === 'ArrowLeft') next = row[k - 1];
  else if (e.key === 'ArrowDown') { for (let j = ri + 1; j < rowKeys.length && !next; j++) next = grid[rowKeys[j]][k]; }
  else if (e.key === 'ArrowUp') { for (let j = ri - 1; j >= 0 && !next; j--) next = grid[rowKeys[j]][k]; }
  else if (e.key === 'Home') next = (e.ctrlKey || e.metaKey) ? grid[rowKeys[0]][0] : row[0];
  else if (e.key === 'End') next = (e.ctrlKey || e.metaKey) ? grid[10][grid[10].length - 1] : row[row.length - 1];
  else return;
  e.preventDefault();
  if (next) focusCell(next, true);
});
table.addEventListener('pointerover', e => { const c = e.target.closest('.mgr-cohort-v'); if (c) describe(c); });
table.addEventListener('click', e => { const c = e.target.closest('.mgr-cohort-v'); if (c) focusCell(c, false); });

function setMode(m, focus) {
  if (m === mode) return;
  mode = m;
  segs.forEach(b => { const on = b.dataset.m === m; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; if (on && focus) b.focus(); });
  table.classList.remove('is-swap'); table.offsetWidth;
  cells.forEach(c => { c.textContent = text(c); });
  table.classList.add('is-swap');
}
segs.forEach(b => b.addEventListener('click', () => setMode(b.dataset.m)));
$('.mgr-cohort-seg').addEventListener('keydown', e => {
  if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) return;
  e.preventDefault(); setMode(mode === 'pct' ? 'users' : 'pct', true);
});

/* edge shadows come from scroll timelines; this is only the fallback */
if (!(window.CSS && CSS.supports('animation-timeline: scroll()'))) {
  scroller.addEventListener('scroll', () => {
    scroller.classList.toggle('is-sx', scroller.scrollLeft > 2);
    scroller.classList.toggle('is-sy', scroller.scrollTop > 2);
  }, { passive: true });
}

