.mgr-deploys {
  --mgr-deploys-bg: oklch(0.205 0.022 155);
  --mgr-deploys-ink: oklch(0.95 0.015 130);
  --mgr-deploys-ok: oklch(0.8 0.15 148);
  --mgr-deploys-fail: oklch(0.7 0.18 27);
  --mgr-deploys-run: oklch(0.86 0.14 88);
  --mgr-deploys-line: color-mix(in oklch, var(--mgr-deploys-ink) 9%, transparent);
  --mgr-deploys-dim: color-mix(in oklch, var(--mgr-deploys-ink) 52%, var(--mgr-deploys-bg));
  --mgr-deploys-raise: color-mix(in oklch, var(--mgr-deploys-ink) 5%, var(--mgr-deploys-bg));
  --mgr-deploys-ease: cubic-bezier(.2, .8, .2, 1);
  --mgr-deploys-spring: linear(0, 0.2 2.5%, 0.69 6.4%, 1.02 11.6%, 1.09 17.4%, 1.03 25.6%, 0.99 38%, 1);
  --mgr-deploys-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  container-type: inline-size; position: relative;
  box-sizing: border-box; width: 100%; max-width: 470px; margin-inline: auto;
  padding: 15px 12px 8px; border-radius: 16px;
  background:
    radial-gradient(80% 45% at 100% 0%, color-mix(in oklch, var(--mgr-deploys-ok) 8%, transparent), transparent 70%),
    var(--mgr-deploys-bg);
  color: var(--mgr-deploys-ink); border: 1px solid var(--mgr-deploys-line);
  font: 400 12.5px/1.3 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--mgr-deploys-run); outline-offset: 1px; border-radius: 8px; }

  & .mgr-deploys-head { display: flex; justify-content: space-between; align-items: center; gap: 10px; margin-bottom: 10px; }
  & .mgr-deploys-head > div:first-child { min-width: 0; }
  & .mgr-deploys-head > :last-child { flex: none; }
  & .mgr-deploys-eyebrow { white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    display: flex; align-items: center; gap: 5px; margin: 0 0 3px; font: 600 10.5px/1 var(--mgr-deploys-mono); color: var(--mgr-deploys-dim);
    & svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 1.3; }
  }
  & h3 { margin: 0; font-size: clamp(17px, 5.8cqi, 21px); font-weight: 680; letter-spacing: -.025em; line-height: 1.05; text-wrap: balance; }
  & .mgr-deploys-rate {
    display: flex; align-items: center; gap: 7px;
    & svg { width: 32px; height: 32px; rotate: -90deg; fill: none; stroke-width: 3.5; }
    & circle { stroke: color-mix(in oklch, var(--mgr-deploys-ink) 10%, transparent); }
    & .mgr-deploys-rate-arc { stroke: var(--mgr-deploys-ok); stroke-linecap: round; stroke-dasharray: var(--r, 0) 100; transition: stroke-dasharray .9s var(--mgr-deploys-ease); }
    & span { display: grid; }
    & b { font: 650 14px/1.1 var(--mgr-deploys-mono); font-variant-numeric: tabular-nums; }
    & small { font-size: 10px; color: var(--mgr-deploys-dim); }
  }

  & .mgr-deploys-filter {
    display: flex; gap: 4px; margin-bottom: 8px;
    & button {
      display: inline-flex; align-items: center; gap: 5px; height: 26px; padding: 0 9px; border-radius: 99px;
      border: 1px solid var(--mgr-deploys-line); background: none; font-size: 11.5px; font-weight: 600; color: var(--mgr-deploys-dim);
      transition: background .25s, color .25s, border-color .25s;
      &:hover { color: var(--mgr-deploys-ink); }
      &[aria-checked="true"] { color: var(--mgr-deploys-bg); background: var(--mgr-deploys-ink); border-color: transparent; }
      & i { font-style: normal; font: 650 10px var(--mgr-deploys-mono); opacity: .7; }
    }
    & [data-f="failed"] i:not(:empty) { color: var(--mgr-deploys-fail); opacity: 1; }
  }

  & .mgr-deploys-list { display: grid; max-height: 360px; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--mgr-deploys-line) transparent; border-top: 1px solid var(--mgr-deploys-line); }
  & .mgr-deploys-item { border-bottom: 1px solid var(--mgr-deploys-line); &[hidden] { display: none; } }
  & .mgr-deploys-row {
    position: relative; width: 100%; display: grid; grid-template-columns: 18px minmax(0, 1fr) auto 38px 12px; align-items: center; gap: 9px;
    padding: 9px 4px; border: 0; background: none; text-align: left; border-radius: 0;
    transition: background .2s;
    &:hover { background: var(--mgr-deploys-raise); }
    &:focus-visible { outline-offset: -2px; }
  }
  & .mgr-deploys-main {
    display: grid; gap: 2px; min-width: 0;
    & b { font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & small { display: flex; align-items: center; gap: 5px; min-width: 0; font-size: 10.5px; color: var(--mgr-deploys-dim); white-space: nowrap; overflow: hidden; }
    & code { font: 600 10px var(--mgr-deploys-mono); color: var(--mgr-deploys-ink); opacity: .8; }
  }
  & .mgr-deploys-av {
    flex: none; display: inline-grid; place-items: center; width: 15px; height: 15px; border-radius: 50%;
    font: 700 7px/1 system-ui, sans-serif; background: oklch(0.45 0.07 var(--h)); color: oklch(0.94 0.04 var(--h));
  }
  & .mgr-deploys-env {
    font: 600 9.5px/1 var(--mgr-deploys-mono); padding: 3px 6px; border-radius: 5px; letter-spacing: .02em;
    background: var(--mgr-deploys-raise); color: var(--mgr-deploys-dim);
  }
  & [data-env="prod"] .mgr-deploys-env { color: var(--mgr-deploys-ink); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mgr-deploys-ink) 22%, transparent); background: none; }
  & .mgr-deploys-dur { justify-self: end; font: 500 11px var(--mgr-deploys-mono); font-variant-numeric: tabular-nums; color: var(--mgr-deploys-dim); }
  & [data-status="running"] .mgr-deploys-dur { color: var(--mgr-deploys-run); }
  & .mgr-deploys-chev { width: 12px; height: 12px; fill: none; stroke: var(--mgr-deploys-dim); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; transition: rotate .45s var(--mgr-deploys-spring); }
  & [aria-expanded="true"] .mgr-deploys-chev { rotate: 180deg; }
  & .mgr-deploys-prog {
    position: absolute; left: 0; right: 0; bottom: -1px; height: 2px; transform-origin: left; transform: scaleX(var(--p, 0));
    background: linear-gradient(90deg, transparent, var(--mgr-deploys-run)); opacity: 0; transition: transform .3s linear, opacity .3s;
  }
  & [data-status="running"] .mgr-deploys-prog { opacity: 1; }

  /* status glyph: one svg, the item's data-status decides which strokes draw */
  & .mgr-deploys-ic {
    width: 16px; height: 16px; flex: none; fill: none; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; overflow: visible;
    & > * { display: none; }
    & .i-ring { display: block; stroke: color-mix(in oklch, currentColor 35%, transparent); }
  }
  & .mgr-deploys-row > .mgr-deploys-ic, & .mgr-deploys-steps li { color: var(--mgr-deploys-dim); }
  & :is([data-status="success"] .mgr-deploys-row, .mgr-deploys-steps li[data-s="ok"]) > .mgr-deploys-ic { color: var(--mgr-deploys-ok); & .i-ok { display: block; stroke: currentColor; } & .i-ring { stroke: currentColor; } }
  & :is([data-status="failed"] .mgr-deploys-row, .mgr-deploys-steps li[data-s="fail"]) > .mgr-deploys-ic { color: var(--mgr-deploys-fail); & .i-fail { display: block; stroke: currentColor; } & .i-ring { stroke: currentColor; } }
  & :is([data-status="running"] .mgr-deploys-row, .mgr-deploys-steps li[data-s="run"]) > .mgr-deploys-ic {
    color: var(--mgr-deploys-run);
    & .i-run { display: block; stroke: currentColor; stroke-dasharray: 28 100; transform-origin: 8px 8px; animation: mgr-deploys-spin 1s linear infinite; animation-play-state: var(--mgr-deploys-play, running); }
  }
  & :is([data-status="queued"] .mgr-deploys-row, .mgr-deploys-steps li[data-s="wait"]) > .mgr-deploys-ic { & .i-wait { display: block; stroke: currentColor; } }
  & :is([data-status="cancelled"] .mgr-deploys-row, .mgr-deploys-steps li[data-s="cancel"]) > .mgr-deploys-ic { & .i-cancel { display: block; stroke: currentColor; } }
  & .mgr-deploys-steps li[data-s="skip"] > .mgr-deploys-ic .i-ring { stroke-dasharray: 2 2.4; }
  & .mgr-deploys-item.is-changed .mgr-deploys-row > .mgr-deploys-ic { animation: mgr-deploys-pop .5s var(--mgr-deploys-spring); }

  /* expanding detail: 0fr to 1fr, children stagger on --i */
  & .mgr-deploys-detail { display: grid; grid-template-rows: 0fr; transition: grid-template-rows .45s var(--mgr-deploys-ease); }
  & .mgr-deploys-in { min-height: 0; overflow: hidden; padding: 0 4px 0 31px; }
  & .mgr-deploys-in > * { opacity: 0; translate: 0 -4px; transition: opacity .25s, translate .4s var(--mgr-deploys-ease); }
  & [aria-expanded="true"] + .mgr-deploys-detail {
    grid-template-rows: 1fr;
    & .mgr-deploys-in > * { opacity: 1; translate: 0 0; transition-delay: calc(var(--i, 0) * 35ms + 80ms); }
  }
  & .mgr-deploys-fall { display: flex; gap: 2px; height: 8px; margin: 2px 0 9px; }
  & .mgr-deploys-seg {
    position: relative; flex: var(--g, 1) 1 0; min-width: 3px; border-radius: 2px; overflow: hidden;
    background: repeating-linear-gradient(-45deg, var(--mgr-deploys-line) 0 3px, transparent 3px 6px);
    transition: flex-grow .3s linear;
    & b { position: absolute; inset: 0; border-radius: inherit; transform-origin: left; transform: scaleX(var(--f, 0)); background: var(--mgr-deploys-ok); transition: transform .3s linear; }
    &[data-s="fail"] b { background: var(--mgr-deploys-fail); }
    &[data-s="run"] b { background: linear-gradient(90deg, color-mix(in oklch, var(--mgr-deploys-run) 55%, transparent), var(--mgr-deploys-run)); }
    &[data-s="cancel"] b { background: var(--mgr-deploys-dim); }
    &[data-s="skip"] { flex: 0 0 6px; background: none; box-shadow: inset 0 0 0 1px var(--mgr-deploys-line); }
  }
  & .mgr-deploys-steps {
    list-style: none; margin: 0 0 8px; padding: 0; display: grid; gap: 1px;
    & li { display: grid; grid-template-columns: 16px minmax(0, 1fr) auto; align-items: center; gap: 8px; height: 22px; font-size: 11.5px; }
    & .mgr-deploys-ic { width: 13px; height: 13px; }
    & .mgr-deploys-sn { color: var(--mgr-deploys-ink); }
    & li[data-s="wait"] .mgr-deploys-sn, & li[data-s="skip"] .mgr-deploys-sn { color: var(--mgr-deploys-dim); }
    & li[data-s="fail"] .mgr-deploys-sn { color: var(--mgr-deploys-fail); font-weight: 600; }
    & .mgr-deploys-sd { font: 500 10.5px var(--mgr-deploys-mono); font-variant-numeric: tabular-nums; color: var(--mgr-deploys-dim); }
    & li[data-s="run"] .mgr-deploys-sd { color: var(--mgr-deploys-run); }
  }
  & .mgr-deploys-log {
    margin: 0 0 8px; padding: 8px 9px; border-radius: 8px; overflow-x: auto; white-space: pre;
    background: color-mix(in oklch, black 30%, var(--mgr-deploys-bg)); border: 1px solid color-mix(in oklch, var(--mgr-deploys-fail) 30%, transparent);
    font: 400 10.5px/1.5 var(--mgr-deploys-mono); color: color-mix(in oklch, var(--mgr-deploys-ink) 85%, transparent);
    & .f { color: var(--mgr-deploys-bg); background: var(--mgr-deploys-fail); padding: 0 3px; border-radius: 3px; font-weight: 700; }
    & .s { color: var(--mgr-deploys-run); }
    & .d { color: var(--mgr-deploys-dim); }
  }
  & :not([data-status="failed"]) > .mgr-deploys-detail .mgr-deploys-log { display: none; }
  & .mgr-deploys-acts {
    display: flex; align-items: center; gap: 6px; padding-bottom: 10px;
    & button {
      display: none; align-items: center; gap: 5px; height: 26px; padding: 0 10px; border-radius: 7px;
      border: 1px solid var(--mgr-deploys-line); background: var(--mgr-deploys-raise); font-size: 11.5px; font-weight: 600;
      & svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; }
      &:hover { border-color: color-mix(in oklch, var(--mgr-deploys-ink) 30%, transparent); }
    }
    & [data-act="retry"] { background: var(--mgr-deploys-ink); color: var(--mgr-deploys-bg); border-color: transparent; }
  }
  & .mgr-deploys-meta { flex: 1; min-width: 0; font: 400 10.5px var(--mgr-deploys-mono); color: var(--mgr-deploys-dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & :is([data-status="failed"], [data-status="cancelled"]) [data-act="retry"],
  & :is([data-status="running"], [data-status="queued"]) [data-act="cancel"] { display: inline-flex; }

  & .mgr-deploys-empty {
    display: grid; justify-items: center; gap: 4px; padding: 26px 10px; text-align: center;
    animation: mgr-deploys-rise .5s var(--mgr-deploys-ease) both;
    &[hidden] { display: none; }
    & svg { width: 32px; height: 32px; margin-bottom: 4px; fill: none; stroke: var(--mgr-deploys-ok); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
    & b { font-weight: 650; }
    & span { font-size: 11.5px; color: var(--mgr-deploys-dim); }
  }
  & .mgr-deploys-live { margin: 7px 2px 0; min-height: 1.3em; font-size: 10.5px; color: var(--mgr-deploys-dim); text-wrap: pretty; }

  @container (width < 340px) {
    & .mgr-deploys-row { grid-template-columns: 16px minmax(0, 1fr) 36px 12px; gap: 8px; }
    & .mgr-deploys-env { display: none; }
