@keyframes mgr-deploys-rise { from { opacity: 0; translate: 0 8px; } }
@media (prefers-reduced-motion: reduce) {
  .mgr-deploys {
    & .mgr-deploys-detail, & .mgr-deploys-chev, & .mgr-deploys-seg, & .mgr-deploys-seg b, & .mgr-deploys-prog { transition: none; }
    & .mgr-deploys-in > *, & [aria-expanded="true"] + .mgr-deploys-detail .mgr-deploys-in > * { translate: 0 0; transition: opacity .2s linear; transition-delay: 0s; }
    & .mgr-deploys-ic .i-run { animation-duration: 3s; }
