const $ = s => root.querySelector(s), $$ = s => [...root.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPEED = 6, STEPS = ['Build', 'Unit tests', 'Integration', 'Deploy', 'Smoke'];
const D = [{id:"9f3c2a1",env:"prod",status:"running",plan:[88,46,60,38,12],t:130},{id:"31be6f2",env:"prod",status:"queued",plan:[92,50,64,40,13],t:0},{id:"4b81e07",env:"prod",status:"failed",plan:[96,52,71,39,12],t:222,failAt:2,failDur:74},{id:"e2d9b44",env:"prod",status:"success",plan:[91,48,62,39,12],t:252},{id:"77ac0f3",env:"staging",status:"success",plan:[84,41,55,36,12],t:228},{id:"c05e1d9",env:"preview",status:"success",plan:[38,9,0,14,5],t:66,skip:[2]}];
const META = { prod: 'fra, iad, sin', staging: 'fra', preview: 'edge preview' };
const uid = 'mgr-deploys-' + Math.random().toString(36).slice(2, 7);
const live = $('[data-live]'), emptyEl = $('.mgr-deploys-empty');
const filterBtns = $$('.mgr-deploys-filter [role="radio"]');
const byId = new Map(D.map(d => [d.id, d]));
const els = new Map($$('.mgr-deploys-item').map(el => [el.dataset.id, el]));
const fmt = s => { s = Math.floor(s); return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0'); };
const plan = d => d.plan.reduce((a, b) => a + b, 0);
let filter = 'all';

function steps(d) {
  const out = []; let acc = 0, cur = false;
  for (let k = 0; k < 5; k++) {
    const exp = d.plan[k];
    if (d.skip && d.skip.includes(k)) { out.push({ s: 'skip', dur: 0, exp: 0 }); continue; }
    if (d.status === 'success') { out.push({ s: 'ok', dur: exp, exp }); continue; }
    if (d.status === 'queued') { out.push({ s: 'wait', dur: 0, exp }); continue; }
    if (d.status === 'failed') {
      if (k < d.failAt) out.push({ s: 'ok', dur: exp, exp });
      else if (k === d.failAt) out.push({ s: 'fail', dur: d.failDur, exp: d.failDur });
      else out.push({ s: 'wait', dur: 0, exp });
      continue;
    }
    /* running or cancelled: steps fill up to elapsed time t */
    if (!cur && d.t >= acc + exp) { out.push({ s: 'ok', dur: exp, exp }); acc += exp; continue; }
    if (!cur) { cur = true; out.push({ s: d.status === 'running' ? 'run' : 'cancel', dur: d.t - acc, exp }); acc += exp; continue; }
    out.push({ s: 'wait', dur: 0, exp });
  }
  return out;
}

function paint(d) {
  const el = els.get(d.id);
  if (el.dataset.status !== d.status) {
    el.classList.remove('is-changed'); el.offsetWidth; el.classList.add('is-changed');
    el.dataset.status = d.status;
  }
  const st = steps(d), total = plan(d);
  el.querySelector('[data-dur]').textContent = d.status === 'queued' ? 'queued' : d.status === 'cancelled' && !d.t ? '\u2014' : fmt(d.t);
  el.querySelector('.mgr-deploys-prog').style.setProperty('--p', d.status === 'running' ? (d.t / total).toFixed(4) : 0);
  el.querySelectorAll('.mgr-deploys-seg').forEach((seg, k) => {
    const s = st[k];
    seg.dataset.s = s.s;
    seg.style.setProperty('--g', Math.max(s.exp, s.dur, 1));
    seg.style.setProperty('--f', s.s === 'ok' || s.s === 'fail' ? 1 : s.s === 'run' || s.s === 'cancel' ? Math.min(1, s.dur / s.exp).toFixed(3) : 0);
  });
  el.querySelectorAll('.mgr-deploys-steps li').forEach((li, k) => {
    const s = st[k];
    li.dataset.s = s.s;
    li.querySelector('.mgr-deploys-sd').textContent =
      s.s === 'skip' ? 'skipped' : s.s === 'wait' ? (d.status === 'failed' ? 'not run' : '~' + fmt(s.exp)) :
      s.s === 'run' ? fmt(s.dur) + ' / ~' + fmt(s.exp) : fmt(s.dur);
  });
  const meta = el.querySelector('[data-meta]');
  meta.textContent = d.status === 'queued' ? 'waiting for ' + (active() ? active().id : 'a runner') :
    d.status === 'running' ? 'eta ' + fmt(Math.max(0, total - d.t)) + ' · ' + META[d.env] :
    d.status === 'failed' ? 'failed at ' + STEPS[d.failAt] + ' · ' + fmt(d.t) :
    d.status === 'cancelled' ? 'cancelled at ' + fmt(d.t) : 'deployed to ' + META[d.env];
  el.querySelector('.mgr-deploys-row').setAttribute('aria-label',
    el.querySelector('.mgr-deploys-main b').textContent + ', ' + d.id + ', ' + d.env + ', ' + d.status + (d.status === 'queued' ? '' : ', ' + fmt(d.t)));
}

function stats() {
  const ok = D.filter(d => d.status === 'success').length, bad = D.filter(d => d.status === 'failed').length;
  $('[data-rate]').textContent = ok + '/' + (ok + bad);
  $('.mgr-deploys-rate-arc').style.setProperty('--r', ok + bad ? (ok / (ok + bad) * 100).toFixed(1) : 0);
  const n = { all: D.length, prod: D.filter(d => d.env === 'prod').length, failed: bad };
  $$('[data-n]').forEach(i => { i.textContent = n[i.dataset.n] || ''; });
  applyFilter();
}
function applyFilter() {
  let shown = 0;
  D.forEach(d => {
    const vis = filter === 'all' || (filter === 'prod' ? d.env === 'prod' : d.status === 'failed');
    els.get(d.id).hidden = !vis; if (vis) shown++;
  });
  emptyEl.hidden = shown > 0;
}

/* ---- disclosure ---- */
els.forEach((el, id) => {
  const btn = el.querySelector('.mgr-deploys-row'), det = el.querySelector('.mgr-deploys-detail');
  det.id = uid + '-' + id; btn.setAttribute('aria-controls', det.id);
  btn.addEventListener('click', () => toggle(el));
});
function toggle(el, force) {
  const btn = el.querySelector('.mgr-deploys-row');
  const open = force != null ? force : btn.getAttribute('aria-expanded') !== 'true';
  btn.setAttribute('aria-expanded', open);
  el.querySelector('.mgr-deploys-detail').inert = !open;
}
$('.mgr-deploys-list').addEventListener('keydown', e => {
  const btn = e.target.closest('.mgr-deploys-row'); if (!btn) return;
  const rows = $$('.mgr-deploys-item:not([hidden]) .mgr-deploys-row'), i = rows.indexOf(btn);
  const to = { ArrowDown: i + 1, ArrowUp: i - 1, Home: 0, End: rows.length - 1 }[e.key];
  if (to != null) { e.preventDefault(); rows[Math.max(0, Math.min(rows.length - 1, to))].focus(); }
  else if (e.key === 'Escape' && btn.getAttribute('aria-expanded') === 'true') { e.preventDefault(); toggle(btn.parentElement, false); }
});

/* ---- filter ---- */
function pick(f, focus) {
  filter = f;
  filterBtns.forEach(b => { const on = b.dataset.f === f; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; if (on && focus) b.focus(); });
  applyFilter();
}
filterBtns.forEach(b => b.addEventListener('click', () => pick(b.dataset.f)));
$('.mgr-deploys-filter').addEventListener('keydown', e => {
  const i = filterBtns.findIndex(b => b.dataset.f === filter);
  const j = { ArrowRight: i + 1, ArrowLeft: i - 1, Home: 0, End: filterBtns.length - 1 }[e.key];
  if (j == null) return;
  e.preventDefault(); pick(filterBtns[(j + filterBtns.length) % filterBtns.length].dataset.f, true);
});

/* ---- the pipeline: one prod runner, FIFO queue, simulated at 6x ---- */
const active = () => D.find(d => d.status === 'running');
function startNext() {
  if (active()) return;
  const next = D.filter(d => d.status === 'queued').sort((a, b) => a.q - b.q)[0];
  if (!next) return;
  next.status = 'running'; next.t = 0;
  live.textContent = (live.textContent ? live.textContent + ' ' : '') + next.id + ' started on ' + next.env + '.';
  paint(next);
  D.filter(d => d.status === 'queued').forEach(paint);
}
let seq = 1;
D.forEach(d => { if (d.status === 'queued') d.q = seq++; });
root.addEventListener('click', e => {
  const b = e.target.closest('[data-act]'); if (!b) return;
  const d = byId.get(b.closest('.mgr-deploys-item').dataset.id);
  live.textContent = '';
  if (b.dataset.act === 'retry') {
    delete d.failAt; delete d.failDur;
    d.status = 'queued'; d.t = 0; d.q = seq++;
    live.textContent = 'Retrying ' + d.id + (active() ? ', queued behind ' + active().id + '.' : '.');
    paint(d); startNext(); stats();
  } else if (b.dataset.act === 'cancel') {
    const was = d.status;
    d.status = 'cancelled';
    live.textContent = d.id + (was === 'queued' ? ' removed from the queue.' : ' cancelled at ' + fmt(d.t) + '.');
    paint(d); startNext(); stats();
  }
  const btn = b.closest('.mgr-deploys-item').querySelector('.mgr-deploys-row');
  if (!b.isConnected || getComputedStyle(b).display === 'none') btn.focus();
});

let visible = true;
const io = new IntersectionObserver(es => { visible = es[es.length - 1].isIntersecting; root.style.setProperty('--mgr-deploys-play', visible ? 'running' : 'paused'); });
io.observe(root);
let last = performance.now();
const timer = setInterval(() => {
  if (!root.isConnected) { clearInterval(timer); io.disconnect(); return; }
  const now = performance.now(), dt = Math.min(1, (now - last) / 1000); last = now;
  if (!visible || document.hidden) return;
  const d = active(); if (!d) return;
  d.t += dt * SPEED;
  const total = plan(d);
  if (d.t >= total) {
    d.t = total; d.status = 'success';
    live.textContent = d.id + ' deployed to ' + d.env + ' in ' + fmt(total) + '.';
    paint(d); stats(); startNext();
  } else paint(d);
}, 250);

D.forEach(paint);
stats();
toggle(els.get('9f3c2a1'), true);
